const HOST_LABEL = "[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?";
const FQDN_PATTERN = new RegExp(`^(?:${HOST_LABEL}\\.)+[A-Za-z]{2,63}$`);
const URL_PATTERN = /^https?:\/\/([^/?#:]+)(?::(\d{1,5}))?([/?#]\S*)?$/i;

function isValidUrl(value: string): boolean {
  const match = URL_PATTERN.exec(value);
  if (match === null) {
    return false;
  }

  const host = match[1];
  if (!FQDN_PATTERN.test(host)) {
    return false;
  }

  const port = match[2];
  if (port !== undefined) {
    const portNumber = Number(port);
    if (portNumber < 1 || portNumber > 65535) {
      return false;
    }
  }

  return true;
}

export function solve(urls: string[]): string[] {
  return urls.filter(isValidUrl);
}

export function solve(word: string, dictionary: string[]): string {
  if (dictionary.length === 0) {
    return "";
  }

  let best = dictionary[0];
  let bestDistance = levenshtein(word, best);

  for (let i = 1; i < dictionary.length; i++) {
    const candidate = dictionary[i];
    const distance = levenshtein(word, candidate);
    if (distance < bestDistance) {
      bestDistance = distance;
      best = candidate;
    }
  }

  return best;
}

function levenshtein(a: string, b: string): number {
  const m = a.length;
  const n = b.length;

  if (m === 0) return n;
  if (n === 0) return m;

  let prev: number[] = new Array<number>(n + 1);
  let curr: number[] = new Array<number>(n + 1);

  for (let j = 0; j <= n; j++) {
    prev[j] = j;
  }

  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(
        prev[j] + 1,        // deletion
        curr[j - 1] + 1,    // insertion
        prev[j - 1] + cost  // substitution or match
      );
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }

  return prev[n];
}

type Key = string | number;
type Container = Record<string | number, unknown>;

const BRACKET = /\[(?:(\d+)|"((?:[^"\\]|\\.)*)"|'((?:[^'\\]|\\.)*)')\]/y;

function parsePath(path: string): Key[] {
  const keys: Key[] = [];
  let i = 0;
  while (i < path.length) {
    const ch = path[i];
    if (ch === ".") {
      i++;
      continue;
    }
    if (ch === "[") {
      BRACKET.lastIndex = i;
      const m = BRACKET.exec(path);
      if (!m) {
        throw new SyntaxError(`Invalid path syntax at index ${i}: ${path}`);
      }
      if (m[1] !== undefined) {
        keys.push(Number(m[1]));
      } else {
        const raw = m[2] ?? m[3] ?? "";
        keys.push(raw.replace(/\\(.)/g, "$1"));
      }
      i = BRACKET.lastIndex;
    } else {
      let j = i;
      while (j < path.length && path[j] !== "." && path[j] !== "[") j++;
      keys.push(path.slice(i, j));
      i = j;
    }
  }
  return keys;
}

function isIndex(key: Key | undefined): key is number {
  return typeof key === "number" && Number.isInteger(key) && key >= 0;
}

export function solve(
  obj: object,
  updates: [string | (string | number)[], unknown][]
): object {
  for (const [path, value] of updates) {
    const keys: Key[] = typeof path === "string" ? parsePath(path) : path;
    if (keys.length === 0) continue;

    let cur = obj as Container;
    for (let k = 0; k < keys.length - 1; k++) {
      const key = keys[k];
      let next = cur[key];
      if (next === null || typeof next !== "object") {
        next = isIndex(keys[k + 1]) ? [] : {};
        cur[key] = next;
      }
      cur = next as Container;
    }
    cur[keys[keys.length - 1]] = value;
  }
  return obj;
}

export function solve(name: string, namespace: string): string {
  // Parse the namespace UUID into 16 bytes.
  const nsHex = namespace.replace(/-/g, "");
  if (!/^[0-9a-fA-F]{32}$/.test(nsHex)) {
    throw new Error("invalid namespace UUID");
  }
  const msg: number[] = [];
  for (let i = 0; i < 32; i += 2) {
    msg.push(parseInt(nsHex.substr(i, 2), 16));
  }

  // Manual UTF-8 encoding of the name (no TextEncoder).
  for (let i = 0; i < name.length; ) {
    const cp = name.codePointAt(i) as number;
    i += cp > 0xffff ? 2 : 1;
    if (cp >= 0xd800 && cp <= 0xdfff) {
      throw new Error("name contains a lone surrogate");
    }
    if (cp < 0x80) {
      msg.push(cp);
    } else if (cp < 0x800) {
      msg.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      msg.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      msg.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  // SHA-1 padding.
  const len = msg.length;
  const bitLenLo = (len * 8) >>> 0;
  const bitLenHi = Math.floor(len / 0x20000000) >>> 0;
  msg.push(0x80);
  while (msg.length % 64 !== 56) {
    msg.push(0);
  }
  msg.push(
    (bitLenHi >>> 24) & 0xff,
    (bitLenHi >>> 16) & 0xff,
    (bitLenHi >>> 8) & 0xff,
    bitLenHi & 0xff,
    (bitLenLo >>> 24) & 0xff,
    (bitLenLo >>> 16) & 0xff,
    (bitLenLo >>> 8) & 0xff,
    bitLenLo & 0xff
  );

  const rotl = (x: number, n: number): number => (x << n) | (x >>> (32 - n));

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  const w: number[] = new Array(80);

  for (let off = 0; off < msg.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const p = off + t * 4;
      w[t] =
        ((msg[p] << 24) | (msg[p + 1] << 16) | (msg[p + 2] << 8) | msg[p + 3]) |
        0;
    }
    for (let t = 16; t < 80; t++) {
      w[t] = rotl(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let t = 0; t < 80; t++) {
      let f: number;
      let k: number;
      if (t < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (t < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (t < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const temp = (rotl(a, 5) + f + e + k + w[t]) >>> 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
  }

  // First 16 bytes of the digest.
  const bytes: number[] = [];
  for (const h of [h0, h1, h2, h3]) {
    bytes.push((h >>> 24) & 0xff, (h >>> 16) & 0xff, (h >>> 8) & 0xff, h & 0xff);
  }

  // Set version (5) and RFC 4122 variant bits.
  bytes[6] = (bytes[6] & 0x0f) | 0x50;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;

  const hex = bytes
    .map((b) => (b < 16 ? "0" : "") + b.toString(16))
    .join("");

  return (
    hex.slice(0, 8) +
    "-" +
    hex.slice(8, 12) +
    "-" +
    hex.slice(12, 16) +
    "-" +
    hex.slice(16, 20) +
    "-" +
    hex.slice(20, 32)
  );
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  const index = new Map<string, number>();
  nodes.forEach((node, i) => {
    if (index.has(node)) {
      throw new Error(`Duplicate node: ${node}`);
    }
    index.set(node, i);
  });

  const adj: number[][] = nodes.map(() => []);
  const indegree: number[] = nodes.map(() => 0);

  for (const [from, to] of edges) {
    const fromIdx = index.get(from);
    const toIdx = index.get(to);
    if (fromIdx === undefined) {
      throw new Error(`Edge references unknown node: ${from}`);
    }
    if (toIdx === undefined) {
      throw new Error(`Edge references unknown node: ${to}`);
    }
    adj[fromIdx].push(toIdx);
    indegree[toIdx]++;
  }

  const queue: number[] = [];
  for (let i = 0; i < nodes.length; i++) {
    if (indegree[i] === 0) {
      queue.push(i);
    }
  }

  const result: string[] = [];
  let head = 0;
  while (head < queue.length) {
    const u = queue[head++];
    result.push(nodes[u]);
    for (const v of adj[u]) {
      indegree[v]--;
      if (indegree[v] === 0) {
        queue.push(v);
      }
    }
  }

  if (result.length !== nodes.length) {
    throw new Error("Cycle detected in edges");
  }

  return result;
}

const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function sextet(ch: string): number {
  const idx = ch.length === 1 ? ALPHABET.indexOf(ch) : -1;
  if (idx < 0) {
    throw new Error(`Invalid base64 character: ${JSON.stringify(ch)}`);
  }
  return idx;
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error("Invalid base64 length: must be a multiple of 4");
  }

  const out: number[] = [];

  for (let i = 0; i < text.length; i += 4) {
    const c0 = text[i];
    const c1 = text[i + 1];
    const c2 = text[i + 2];
    const c3 = text[i + 3];

    const isLastGroup = i + 4 === text.length;
    const pad2 = c2 === "=";
    const pad3 = c3 === "=";

    if ((pad2 || pad3) && !isLastGroup) {
      throw new Error("Invalid base64: padding only allowed at the end");
    }
    if (pad2 && !pad3) {
      throw new Error("Invalid base64: malformed padding");
    }

    const v0 = sextet(c0);
    const v1 = sextet(c1);
    const v2 = pad2 ? 0 : sextet(c2);
    const v3 = pad3 ? 0 : sextet(c3);

    const n = (v0 << 18) | (v1 << 12) | (v2 << 6) | v3;

    out.push((n >> 16) & 0xff);
    if (!pad2) {
      out.push((n >> 8) & 0xff);
    }
    if (!pad3) {
      out.push(n & 0xff);
    }
  }

  return out;
}

export function solve(epochMs: number): string {
  // Drop any sub-second part by flooring to whole seconds (also correct for negative times).
  const wholeSecondsMs = Math.floor(epochMs / 1000) * 1000;
  // toISOString always emits UTC with milliseconds; strip the ".000" before the "Z".
  return new Date(wholeSecondsMs).toISOString().replace(/\.\d{3}Z$/, "Z");
}

export function solve(text: string): string {
  // 1. UTF-8 encode manually (lone surrogates become U+FFFD, matching TextEncoder behavior)
  const bytes: number[] = [];
  for (const ch of text) {
    let cp = ch.codePointAt(0) as number;
    if (cp >= 0xd800 && cp <= 0xdfff) cp = 0xfffd;
    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  // 2. Padding: 0x80, zeros until length ≡ 56 (mod 64), then 64-bit little-endian bit length
  const bitLenLo = (bytes.length * 8) >>> 0;
  const bitLenHi = Math.floor(bytes.length / 0x20000000) >>> 0;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let i = 0; i < 4; i++) bytes.push((bitLenLo >>> (8 * i)) & 0xff);
  for (let i = 0; i < 4; i++) bytes.push((bitLenHi >>> (8 * i)) & 0xff);

  // 3. Constants
  const K: number[] = [];
  for (let i = 0; i < 64; i++) {
    K[i] = Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296) >>> 0;
  }
  const S: number[] = [
    7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
    5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
    4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
    6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
  ];

  let a0 = 0x67452301;
  let b0 = 0xefcdab89 | 0;
  let c0 = 0x98badcfe | 0;
  let d0 = 0x10325476;

  const M: number[] = new Array(16);

  // 4. Process each 512-bit block
  for (let off = 0; off < bytes.length; off += 64) {
    for (let j = 0; j < 16; j++) {
      const p = off + j * 4;
      M[j] =
        bytes[p] |
        (bytes[p + 1] << 8) |
        (bytes[p + 2] << 16) |
        (bytes[p + 3] << 24);
    }

    let A = a0;
    let B = b0;
    let C = c0;
    let D = d0;

    for (let i = 0; i < 64; i++) {
      let F: number;
      let g: number;
      if (i < 16) {
        F = (B & C) | (~B & D);
        g = i;
      } else if (i < 32) {
        F = (D & B) | (~D & C);
        g = (5 * i + 1) % 16;
      } else if (i < 48) {
        F = B ^ C ^ D;
        g = (3 * i + 5) % 16;
      } else {
        F = C ^ (B | ~D);
        g = (7 * i) % 16;
      }

      F = (F + A + K[i] + M[g]) | 0;
      A = D;
      D = C;
      C = B;
      const s = S[i];
      B = (B + ((F << s) | (F >>> (32 - s)))) | 0;
    }

    a0 = (a0 + A) | 0;
    b0 = (b0 + B) | 0;
    c0 = (c0 + C) | 0;
    d0 = (d0 + D) | 0;
  }

  // 5. Output digest as little-endian bytes in lowercase hex
  const words = [a0, b0, c0, d0];
  let hex = "";
  for (const w of words) {
    for (let k = 0; k < 4; k++) {
      const byte = (w >>> (8 * k)) & 0xff;
      hex += (byte < 16 ? "0" : "") + byte.toString(16);
    }
  }
  return hex;
}

type TypedArray =
  | Int8Array
  | Uint8Array
  | Uint8ClampedArray
  | Int16Array
  | Uint16Array
  | Int32Array
  | Uint32Array
  | Float32Array
  | Float64Array
  | BigInt64Array
  | BigUint64Array;

export function solve<T>(value: T): T {
  // Maps every already-copied source object to its copy.
  // This preserves shared references and makes cycles map onto cycles.
  const seen = new Map<object, unknown>();

  const copy = (input: unknown): unknown => {
    // Primitives and functions are returned as-is.
    if (input === null || (typeof input !== "object")) {
      return input;
    }

    const src = input as object;
    if (seen.has(src)) {
      return seen.get(src);
    }

    // Date
    if (src instanceof Date) {
      const out = new Date(src.getTime());
      seen.set(src, out);
      return out;
    }

    // RegExp
    if (src instanceof RegExp) {
      const out = new RegExp(src.source, src.flags);
      out.lastIndex = src.lastIndex;
      seen.set(src, out);
      return out;
    }

    // ArrayBuffer
    if (src instanceof ArrayBuffer) {
      const out = src.slice(0);
      seen.set(src, out);
      return out;
    }

    // Typed arrays and DataView (views over an ArrayBuffer)
    if (ArrayBuffer.isView(src)) {
      // Copy the underlying buffer through the same `seen` map so that
      // views sharing a buffer still share one copied buffer.
      const buffer = copy(src.buffer) as ArrayBuffer;
      let out: ArrayBufferView;

      if (src instanceof DataView) {
        out = new DataView(buffer, src.byteOffset, src.byteLength);
      } else {
        const typed = src as unknown as TypedArray;
        const Ctor = (src as unknown as { constructor: unknown })
          .constructor as unknown as new (
          buffer: ArrayBuffer,
          byteOffset: number,
          length: number
        ) => TypedArray;
        out = new Ctor(buffer, typed.byteOffset, typed.length);
      }

      seen.set(src, out);
      return out;
    }

    // Map: clone both keys and values
    if (src instanceof Map) {
      const out = new Map<unknown, unknown>();
      seen.set(src, out);
      for (const [k, v] of src) {
        out.set(copy(k), copy(v));
      }
      return out;
    }

    // Set: clone each element
    if (src instanceof Set) {
      const out = new Set<unknown>();
      seen.set(src, out);
      for (const v of src) {
        out.add(copy(v));
      }
      return out;
    }

    // WeakMap / WeakSet cannot be enumerated or copied; keep the reference.
    if (src instanceof WeakMap || src instanceof WeakSet) {
      return src;
    }

    // Arrays and plain/class objects: copy own enumerable properties
    // (string and symbol keys), preserving the prototype.
    const out: Record<PropertyKey, unknown> = Array.isArray(src)
      ? (new Array((src as unknown[]).length) as unknown as Record<PropertyKey, unknown>)
      : (Object.create(Object.getPrototypeOf(src)) as Record<PropertyKey, unknown>);

    seen.set(src, out);

    for (const key of Reflect.ownKeys(src)) {
      const desc = Object.getOwnPropertyDescriptor(src, key);
      if (!desc || !desc.enumerable) {
        continue;
      }
      const childValue = (src as Record<PropertyKey, unknown>)[key];
      Object.defineProperty(out, key, {
        value: copy(childValue),
        writable: true,
        enumerable: true,
        configurable: true,
      });
    }

    return out;
  };

  return copy(value) as T;
}

export function solve(stamps: string[]): number[] {
  return stamps.map(parseIso8601).sort((a, b) => a - b);
}

const ISO_RE =
  /^(\d{4})(?:-(\d{2})-(\d{2})|-W(\d{2})-([1-7])|-(\d{3}))(?:T(\d{2}):(\d{2})(?::(\d{2})(?:[.,](\d+))?)?(Z|([+-])(\d{2}):(\d{2}))?)?$/;

function invalid(input: unknown): RangeError {
  return new RangeError(`Invalid ISO 8601 date: ${String(input)}`);
}

function isLeap(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, m: number): number {
  return [31, isLeap(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];
}

/** Days since 1970-01-01 for a proleptic Gregorian date (m is 1-12). */
function daysFromCivil(y: number, m: number, d: number): number {
  const yy = m <= 2 ? y - 1 : y;
  const era = Math.floor(yy / 400);
  const yoe = yy - era * 400;
  const mp = (m + 9) % 12; // March = 0
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

/** ISO weekday (Monday = 1 ... Sunday = 7) for a day number. 1970-01-01 was a Thursday. */
function isoWeekday(days: number): number {
  return ((((days + 3) % 7) + 7) % 7) + 1;
}

function parseIso8601(input: string): number {
  if (typeof input !== "string") throw invalid(input);
  const m = ISO_RE.exec(input);
  if (!m) throw invalid(input);

  const year = Number(m[1]);
  let days: number;

  if (m[2] !== undefined) {
    // Calendar date: YYYY-MM-DD
    const month = Number(m[2]);
    const day = Number(m[3]);
    if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) {
      throw invalid(input);
    }
    days = daysFromCivil(year, month, day);
  } else if (m[4] !== undefined) {
    // Week date: YYYY-Www-D
    const week = Number(m[4]);
    const weekday = Number(m[5]);
    const jan1Weekday = isoWeekday(daysFromCivil(year, 1, 1));
    const weeksInYear =
      jan1Weekday === 4 || (isLeap(year) && jan1Weekday === 3) ? 53 : 52;
    if (week < 1 || week > weeksInYear) throw invalid(input);

    // ISO week 1 is the week containing January 4th.
    const jan4 = daysFromCivil(year, 1, 4);
    const mondayWeek1 = jan4 - (isoWeekday(jan4) - 1);
    days = mondayWeek1 + (week - 1) * 7 + (weekday - 1);
  } else {
    // Ordinal date: YYYY-DDD
    const ordinal = Number(m[6]);
    const maxOrdinal = isLeap(year) ? 366 : 365;
    if (ordinal < 1 || ordinal > maxOrdinal) throw invalid(input);
    days = daysFromCivil(year, 1, 1) + (ordinal - 1);
  }

  let timeMs = 0;
  let offsetMinutes = 0;

  if (m[7] !== undefined) {
    // Time: hh:mm[:ss[.fraction]]
    const hour = Number(m[7]);
    const minute = Number(m[8]);
    const second = m[9] !== undefined ? Number(m[9]) : 0;
    const fraction = m[10] || "";

    if (minute > 59 || second > 59) throw invalid(input);
    if (hour === 24) {
      // 24:00:00 is the end of the day and is valid only with zero minutes/seconds/fraction.
      if (minute !== 0 || second !== 0 || !/^0*$/.test(fraction)) throw invalid(input);
    } else if (hour > 23) {
      throw invalid(input);
    }

    // Truncate fractional seconds to whole milliseconds.
    const millis = Number((fraction + "000").slice(0, 3));
    timeMs = (hour * 3600 + minute * 60 + second) * 1000 + millis;

    // Offset: Z, or ±hh:mm. Absent offset means UTC.
    if (m[11] !== undefined && m[11] !== "Z") {
      const sign = m[12] === "-" ? -1 : 1;
      const offH = Number(m[13]);
      const offM = Number(m[14]);
      if (offH > 23 || offM > 59) throw invalid(input);
      offsetMinutes = sign * (offH * 60 + offM);
    }
  }

  return days * 86400000 + timeMs - offsetMinutes * 60000;
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

interface ParsedVersion {
  full: string;
  nums: [string, string, string];
  pre: string[] | null;
}

function cmpStr(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

// Compares non-negative integer strings (no leading zeros) without overflow.
function cmpNumStr(a: string, b: string): number {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  return cmpStr(a, b);
}

function isNumeric(s: string): boolean {
  return /^\d+$/.test(s);
}

function parse(v: string): ParsedVersion {
  const plus = v.indexOf("+");
  const main = plus === -1 ? v : v.slice(0, plus);
  const dash = main.indexOf("-");
  const core = dash === -1 ? main : main.slice(0, dash);
  const pre = dash === -1 ? null : main.slice(dash + 1).split(".");
  const parts = core.split(".");
  return {
    full: v,
    nums: [parts[0], parts[1], parts[2]],
    pre,
  };
}

function comparePrecedence(a: ParsedVersion, b: ParsedVersion): number {
  for (let i = 0; i < 3; i++) {
    const c = cmpNumStr(a.nums[i], b.nums[i]);
    if (c !== 0) return c;
  }

  // A version without prerelease has higher precedence than one with it.
  if (a.pre === null && b.pre === null) return 0;
  if (a.pre === null) return 1;
  if (b.pre === null) return -1;

  const len = Math.min(a.pre.length, b.pre.length);
  for (let i = 0; i < len; i++) {
    const x = a.pre[i];
    const y = b.pre[i];
    if (x === y) continue;

    const xNum = isNumeric(x);
    const yNum = isNumeric(y);
    let c: number;
    if (xNum && yNum) {
      c = cmpNumStr(x, y);
    } else if (xNum) {
      c = -1; // numeric identifiers have lower precedence
    } else if (yNum) {
      c = 1;
    } else {
      c = cmpStr(x, y);
    }
    if (c !== 0) return c;
  }

  // Shorter identifier list is lower when all preceding identifiers are equal.
  if (a.pre.length !== b.pre.length) {
    return a.pre.length < b.pre.length ? -1 : 1;
  }
  return 0;
}

export function solve(versions: string[]): string[] {
  return versions
    .filter((v) => SEMVER_RE.test(v))
    .map(parse)
    .sort((a, b) => comparePrecedence(a, b) || cmpStr(a.full, b.full))
    .map((p) => p.full);
}

type Kind = 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease';

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*)?$/;

const ID_RE = /^[0-9a-zA-Z-]+$/;

const isNumeric = (s: string): boolean => /^\d+$/.test(s);

/**
 * Computes the next prerelease identifier list.
 * `cur` is the current prerelease identifiers (empty for a release),
 * `ident` is the optional prerelease identifier (e.g. "beta").
 */
function nextPrerelease(cur: string[], ident: string | undefined): string[] {
  if (cur.length === 0) {
    return ident !== undefined ? [ident, '0'] : ['0'];
  }

  // Different identifier: switch to <id>.0
  if (ident !== undefined && cur[0] !== ident) {
    return [ident, '0'];
  }

  // Same identifier, or no identifier: increment the last numeric part
  const p = [...cur];
  let i = p.length - 1;
  while (i >= 0 && !isNumeric(p[i])) i--;

  if (i >= 0) {
    p[i] = String(Number(p[i]) + 1);
  } else {
    p.push('0');
  }

  // Same identifier but no usable numeric counter right after it: reset to <id>.0
  if (ident !== undefined && (p.length < 2 || !isNumeric(p[1]))) {
    return [ident, '0'];
  }

  return p;
}

export function solve(
  version: string,
  kind: Kind,
  id?: string
): string | null {
  const m = typeof version === 'string' ? SEMVER_RE.exec(version) : null;
  if (!m) return null;

  if (id !== undefined && !ID_RE.test(id)) return null;

  let major = Number(m[1]);
  let minor = Number(m[2]);
  let patch = Number(m[3]);
  let pre: string[] = m[4] ? m[4].split('.') : [];
  const hasPre = pre.length > 0;

  switch (kind) {
    case 'major':
      if (hasPre && minor === 0 && patch === 0) {
        // Release the prerelease without bumping
      } else {
        major++;
        minor = 0;
        patch = 0;
      }
      pre = [];
      break;

    case 'minor':
      if (hasPre && patch === 0) {
        // Release the prerelease without bumping
      } else {
        minor++;
        patch = 0;
      }
      pre = [];
      break;

    case 'patch':
      if (!hasPre) {
        patch++;
      }
      pre = [];
      break;

    case 'premajor':
      major++;
      minor = 0;
      patch = 0;
      pre = nextPrerelease([], id);
      break;

    case 'preminor':
      minor++;
      patch = 0;
      pre = nextPrerelease([], id);
      break;

    case 'prepatch':
      patch++;
      pre = nextPrerelease([], id);
      break;

    case 'prerelease':
      if (!hasPre) {
        patch++;
        pre = nextPrerelease([], id);
      } else {
        pre = nextPrerelease(pre, id);
      }
      break;

    default:
      return null;
  }

  const core = `${major}.${minor}.${patch}`;
  return pre.length > 0 ? `${core}-${pre.join('.')}` : core;
}

export function solve(text: string): string {
  // UTF-8 encode manually (no TextEncoder); lone surrogates become U+FFFD as in TextEncoder.
  const bytes: number[] = [];
  for (let i = 0; i < text.length; i++) {
    let c = text.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < text.length) {
      const d = text.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) {
        c = 0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00);
        i++;
      }
    }
    if (c >= 0xd800 && c <= 0xdfff) c = 0xfffd;

    if (c < 0x80) {
      bytes.push(c);
    } else if (c < 0x800) {
      bytes.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f));
    } else if (c < 0x10000) {
      bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
    } else {
      bytes.push(
        0xf0 | (c >> 18),
        0x80 | ((c >> 12) & 0x3f),
        0x80 | ((c >> 6) & 0x3f),
        0x80 | (c & 0x3f)
      );
    }
  }

  // Padding (FIPS 180-4 section 5.1.1)
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  bytes.push(
    (hi >>> 24) & 0xff, (hi >>> 16) & 0xff, (hi >>> 8) & 0xff, hi & 0xff,
    (lo >>> 24) & 0xff, (lo >>> 16) & 0xff, (lo >>> 8) & 0xff, lo & 0xff
  );

  let h0 = 0x67452301 | 0;
  let h1 = 0xefcdab89 | 0;
  let h2 = 0x98badcfe | 0;
  let h3 = 0x10325476 | 0;
  let h4 = 0xc3d2e1f0 | 0;

  const w: number[] = new Array<number>(80).fill(0);

  for (let o = 0; o < bytes.length; o += 64) {
    for (let t = 0; t < 16; t++) {
      const p = o + t * 4;
      w[t] = (bytes[p] << 24) | (bytes[p + 1] << 16) | (bytes[p + 2] << 8) | bytes[p + 3];
    }
    for (let t = 16; t < 80; t++) {
      const x = w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16];
      w[t] = (x << 1) | (x >>> 31);
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let t = 0; t < 80; t++) {
      let f: number;
      let k: number;
      if (t < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (t < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (t < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const temp = (((a << 5) | (a >>> 27)) + f + e + k + w[t]) | 0;
      e = d;
      d = c;
      c = (b << 30) | (b >>> 2);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) | 0;
    h1 = (h1 + b) | 0;
    h2 = (h2 + c) | 0;
    h3 = (h3 + d) | 0;
    h4 = (h4 + e) | 0;
  }

  const hex = (x: number): string => (x >>> 0).toString(16).padStart(8, "0");
  return hex(h0) + hex(h1) + hex(h2) + hex(h3) + hex(h4);
}

type Parsed = { core: [string, string, string]; pre: string[] };

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*)?$/;

const NUMERIC_RE = /^\d+$/;

function parse(v: string): Parsed {
  const m = SEMVER_RE.exec(v);
  if (!m) throw new Error(`Invalid semver version: ${v}`);
  return {
    core: [m[1], m[2], m[3]],
    pre: m[4] !== undefined ? m[4].split(".") : [],
  };
}

// Compare non-negative integer strings without precision loss.
function cmpNum(x: string, y: string): number {
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  return x < y ? -1 : x > y ? 1 : 0;
}

function cmpIdent(x: string, y: string): number {
  const xn = NUMERIC_RE.test(x);
  const yn = NUMERIC_RE.test(y);
  if (xn && yn) return cmpNum(x, y);
  if (xn) return -1; // numeric identifiers have lower precedence
  if (yn) return 1;
  return x < y ? -1 : x > y ? 1 : 0;
}

function comparePre(x: string[], y: string[]): number {
  if (x.length === 0 && y.length === 0) return 0;
  if (x.length === 0) return 1; // release > prerelease
  if (y.length === 0) return -1;
  const n = Math.min(x.length, y.length);
  for (let i = 0; i < n; i++) {
    const c = cmpIdent(x[i], y[i]);
    if (c !== 0) return c;
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1;
}

function compareVersions(x: Parsed, y: Parsed): number {
  for (let i = 0; i < 3; i++) {
    const c = cmpNum(x.core[i], y.core[i]);
    if (c !== 0) return c;
  }
  return comparePre(x.pre, y.pre);
}

export function solve(a: string, b: string): string | null {
  const pa = parse(a);
  const pb = parse(b);

  const c = compareVersions(pa, pb);
  if (c === 0) return null;

  const lo = c < 0 ? pa : pb;
  const hi = c < 0 ? pb : pa;

  const loPre = lo.pre.length > 0;
  const hiPre = hi.pre.length > 0;

  const dMajor = lo.core[0] !== hi.core[0];
  const dMinor = lo.core[1] !== hi.core[1];
  const dPatch = lo.core[2] !== hi.core[2];

  let part: "major" | "minor" | "patch" | null = null;
  if (dMajor) part = "major";
  else if (dMinor) part = "minor";
  else if (dPatch) part = "patch";

  if (loPre && !hiPre) {
    // Prerelease -> release
    if (part !== null) {
      // Highest differing part; the "only X changed" exceptions coincide with this.
      return part;
    }
    // Cores equal: classify by the lower's minor/patch being zero.
    const loMinor = lo.core[1];
    const loPatch = lo.core[2];
    if (loMinor === "0" && loPatch === "0") return "major";
    if (loPatch === "0") return "minor";
    return "patch";
  }

  // Higher is a prerelease (or both are releases, which cannot have equal cores here)
  if (part === null) return "prerelease";
  return hiPre ? "pre" + part : part;
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  // Ignore spaces and hyphens only
  const s = isbn.replace(/[ -]/g, "");

  const isValid10 = (t: string): boolean => {
    // Nine digits followed by a digit or an upper-case 'X' check character
    if (!/^[0-9]{9}[0-9X]$/.test(t)) return false;
    let sum = 0;
    for (let i = 0; i < 10; i++) {
      const ch = t[i];
      const value = ch === "X" ? 10 : ch.charCodeAt(0) - 48;
      sum += (10 - i) * value;
    }
    return sum % 11 === 0;
  };

  const isValid13 = (t: string): boolean => {
    if (!/^[0-9]{13}$/.test(t)) return false;
    let sum = 0;
    for (let i = 0; i < 13; i++) {
      const weight = i % 2 === 0 ? 1 : 3;
      sum += weight * (t.charCodeAt(i) - 48);
    }
    return sum % 10 === 0;
  };

  if (version === 10) return isValid10(s);
  if (version === 13) return isValid13(s);
  return isValid10(s) || isValid13(s);
}

export function solve(name: string, namespace: string): string {
  if (typeof namespace !== "string" ||
      !/^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(namespace)) {
    throw new TypeError("namespace is not a valid UUID");
  }
  if (typeof name !== "string") {
    throw new TypeError("name must be a string");
  }

  // Parse namespace UUID into 16 bytes.
  const hex = namespace.replace(/-/g, "");
  const nsBytes: number[] = [];
  for (let i = 0; i < 32; i += 2) {
    nsBytes.push(parseInt(hex.slice(i, i + 2), 16));
  }

  // UTF-8 encode the name (lone surrogates become U+FFFD, as in standard UTF-8 encoding).
  const utf8: number[] = [];
  for (let i = 0; i < name.length; i++) {
    let cp = name.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < name.length) {
      const lo = name.charCodeAt(i + 1);
      if (lo >= 0xdc00 && lo <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
        i++;
      } else {
        cp = 0xfffd;
      }
    } else if (cp >= 0xd800 && cp <= 0xdfff) {
      cp = 0xfffd;
    }
    if (cp < 0x80) {
      utf8.push(cp);
    } else if (cp < 0x800) {
      utf8.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      utf8.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      utf8.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  const digest = md5(nsBytes.concat(utf8));

  // Set version (3) and RFC 4122 variant bits.
  digest[6] = (digest[6] & 0x0f) | 0x30;
  digest[8] = (digest[8] & 0x3f) | 0x80;

  let out = "";
  for (let i = 0; i < 16; i++) {
    out += (digest[i] < 16 ? "0" : "") + digest[i].toString(16);
    if (i === 3 || i === 5 || i === 7 || i === 9) {
      out += "-";
    }
  }
  return out;
}

function md5(msg: number[]): number[] {
  const S = [
    7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
    5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
    4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
    6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21
  ];

  const K: number[] = [];
  for (let i = 0; i < 64; i++) {
    K[i] = Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296) | 0;
  }

  // Padding
  const bitLen = msg.length * 8;
  const padded = msg.slice();
  padded.push(0x80);
  while (padded.length % 64 !== 56) {
    padded.push(0);
  }
  const lo = bitLen >>> 0;
  const hi = Math.floor(bitLen / 4294967296) >>> 0;
  for (let i = 0; i < 4; i++) padded.push((lo >>> (8 * i)) & 0xff);
  for (let i = 0; i < 4; i++) padded.push((hi >>> (8 * i)) & 0xff);

  let a0 = 0x67452301 | 0;
  let b0 = 0xefcdab89 | 0;
  let c0 = 0x98badcfe | 0;
  let d0 = 0x10325476 | 0;

  const M: number[] = new Array(16);

  for (let off = 0; off < padded.length; off += 64) {
    for (let j = 0; j < 16; j++) {
      const p = off + j * 4;
      M[j] = padded[p] | (padded[p + 1] << 8) | (padded[p + 2] << 16) | (padded[p + 3] << 24);
    }

    let A = a0, B = b0, C = c0, D = d0;

    for (let i = 0; i < 64; i++) {
      let F: number;
      let g: number;
      if (i < 16) {
        F = (B & C) | (~B & D);
        g = i;
      } else if (i < 32) {
        F = (D & B) | (~D & C);
        g = (5 * i + 1) & 15;
      } else if (i < 48) {
        F = B ^ C ^ D;
        g = (3 * i + 5) & 15;
      } else {
        F = C ^ (B | ~D);
        g = (7 * i) & 15;
      }
      F = (F + A + K[i] + M[g]) | 0;
      A = D;
      D = C;
      C = B;
      B = (B + ((F << S[i]) | (F >>> (32 - S[i])))) | 0;
    }

    a0 = (a0 + A) | 0;
    b0 = (b0 + B) | 0;
    c0 = (c0 + C) | 0;
    d0 = (d0 + D) | 0;
  }

  const out: number[] = [];
  const words = [a0, b0, c0, d0];
  for (let w = 0; w < 4; w++) {
    for (let i = 0; i < 4; i++) {
      out.push((words[w] >>> (8 * i)) & 0xff);
    }
  }
  return out;
}

