  MT: { length: 31, bban: "4a5n18c" },
  MU: { length: 30, bban: "4a2n2n12n3n3a" },
  NI: { length: 28, bban: "4a20n" },
  NL: { length: 18, bban: "4a10n" },
  NO: { length: 15, bban: "4n6n1n" },
  OM: { length: 23, bban: "3n16c" },
  PK: { length: 24, bban: "4a16c" },
  PL: { length: 28, bban: "8n16n" },
  PS: { length: 29, bban: "4a21c" },
  PT: { length: 25, bban: "4n4n11n2n" },
  QA: { length: 29, bban: "4a21c" },
  RO: { length: 24, bban: "4a16c" },
  RS: { length: 22, bban: "3n13n2n" },
  RU: { length: 33, bban: "9n5n15c" },
  SA: { length: 24, bban: "2n18c" },
  SC: { length: 31, bban: "4a2n2n16n3a" },
  SD: { length: 18, bban: "2n12n" },
  SE: { length: 24, bban: "3n16n1n" },
  SI: { length: 19, bban: "5n8n2n" },
  SK: { length: 24, bban: "4n6n10n" },
  SM: { length: 27, bban: "1a5n5n12c" },
  ST: { length: 25, bban: "4n4n11n2n" },
  SV: { length: 28, bban: "4a20n" },
  TL: { length: 23, bban: "3n14n2n" },
  TN: { length: 24, bban: "2n3n13n2n" },
  TR: { length: 26, bban: "5n1n16c" },
  UA: { length: 29, bban: "6n19c" },
  VA: { length: 22, bban: "3n15n" },
  VG: { length: 24, bban: "4a16n" },
  XK: { length: 20, bban: "4n10n2n" },
};

// Build a anchored regular expression for each country's BBAN structure.
const BBAN_PATTERNS: Map<string, RegExp> = new Map();
for (const [country, entry] of Object.entries(IBAN_REGISTRY)) {
  let source = "";
  const tokenRe = /(\d+)([nac])/g;
  let match: RegExpExecArray | null;
  while ((match = tokenRe.exec(entry.bban)) !== null) {
    const count = Number(match[1]);
    const type = match[2];
    const charClass = type === "n" ? "[0-9]" : type === "a" ? "[A-Z]" : "[A-Z0-9]";
    source += `${charClass}{${count}}`;
  }
  BBAN_PATTERNS.set(country, new RegExp(`^${source}$`));
}

export function solve(iban: string): boolean {
  // Remove spaces and hyphens, then normalise letters to uppercase.
  const normalized = iban.replace(/[\s-]/g, "").toUpperCase();

  // Country code (2 letters) and check digits (2 digits).
  if (!/^[A-Z]{2}[0-9]{2}/.test(normalized)) {
    return false;
  }

  const country = normalized.slice(0, 2);
  const entry = IBAN_REGISTRY[country];
  if (entry === undefined) {
    return false;
  }

  // Total length must match the registry entry.
  if (normalized.length !== entry.length) {
    return false;
  }

  // BBAN must match the country's character structure.
  const bban = normalized.slice(4);
  const bbanPattern = BBAN_PATTERNS.get(country);
  if (bbanPattern === undefined || !bbanPattern.test(bban)) {
    return false;
  }

  // Mod-97 check: move the first four characters to the end and
  // compute the remainder, treating A=10 ... Z=35.
  const rearranged = bban + normalized.slice(0, 4);
  let remainder = 0;
  for (let i = 0; i < rearranged.length; i++) {
    const code = rearranged.charCodeAt(i);
    if (code >= 48 && code <= 57) {
      // Digit 0-9
      remainder = (remainder * 10 + (code - 48)) % 97;
    } else {
      // Letter A-Z -> two-digit value 10-35
      remainder = (remainder * 100 + (code - 55)) % 97;
    }
  }

  return remainder === 1;
}

type Issuer = {
  matches: (digits: string) => boolean;
  lengths: readonly number[];
};

const range = (from: number, to: number): number[] => {
  const out: number[] = [];
  for (let n = from; n <= to; n++) out.push(n);
  return out;
};

// Returns the first n digits as a number, or NaN if the string is shorter than n.
const prefix = (digits: string, n: number): number =>
  digits.length >= n ? Number(digits.slice(0, n)) : NaN;

const inRange = (value: number, lo: number, hi: number): boolean =>
  value >= lo && value <= hi;

const ISSUERS: readonly Issuer[] = [
  // Visa
  {
    matches: (d) => d.startsWith("4"),
    lengths: [13, 16, 19],
  },
  // Mastercard
  {
    matches: (d) =>
      inRange(prefix(d, 2), 51, 55) || inRange(prefix(d, 4), 2221, 2720),
    lengths: [16],
  },
  // American Express
  {
    matches: (d) => {
      const p = prefix(d, 2);
      return p === 34 || p === 37;
    },
    lengths: [15],
  },
  // Discover
  {
    matches: (d) =>
      d.startsWith("6011") ||
      inRange(prefix(d, 6), 622126, 622925) ||
      inRange(prefix(d, 3), 644, 649) ||
      prefix(d, 2) === 65,
    lengths: [16, 19],
  },
  // Diners Club
  {
    matches: (d) => {
      const p2 = prefix(d, 2);
      return inRange(prefix(d, 3), 300, 305) || p2 === 36 || p2 === 38;
    },
    lengths: range(14, 19),
  },
  // JCB
  {
    matches: (d) => inRange(prefix(d, 4), 3528, 3589),
    lengths: range(16, 19),
  },
  // UnionPay
  {
    matches: (d) => prefix(d, 2) === 62,
    lengths: range(16, 19),
  },
];

const passesLuhn = (digits: string): boolean => {
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let n = digits.charCodeAt(i) - 48;
    if (double) {
      n *= 2;
      if (n > 9) n -= 9;
    }
    sum += n;
    double = !double;
  }
  return sum % 10 === 0;
};

export function solve(card: string): boolean {
  const digits = card.replace(/[\s-]/g, "");
  if (!/^\d+$/.test(digits)) return false;

  const issuerMatch = ISSUERS.some(
    (issuer) =>
      issuer.matches(digits) && issuer.lengths.includes(digits.length)
  );
  if (!issuerMatch) return false;

  return passesLuhn(digits);
}

const HEX_GROUP = /^[0-9A-Fa-f]{1,4}$/;
const IPV4_OCTET = /^(0|[1-9][0-9]{0,2})$/;
const ZONE_ID = /^[A-Za-z0-9]+$/;

function isIPv4(s: string): boolean {
  const parts = s.split(".");
  if (parts.length !== 4) return false;
  return parts.every((p) => IPV4_OCTET.test(p) && Number(p) <= 255);
}

// Parses an IPv6 address without zone index into 8 16-bit groups, or returns null.
function parseIPv6(input: string): number[] | null {
  let addr = input;

  // Embedded dotted IPv4 occupies the last two groups; validate it and
  // replace it with two placeholder hex groups so the rest of the parse is uniform.
  if (addr.includes(".")) {
    const idx = addr.lastIndexOf(":");
    if (idx === -1) return null;
    if (!isIPv4(addr.slice(idx + 1))) return null;
    addr = addr.slice(0, idx + 1) + "0:0";
  }

  const dbl = addr.indexOf("::");
  if (dbl !== -1) {
    // At most one "::" (this also rejects ":::").
    if (addr.indexOf("::", dbl + 1) !== -1) return null;

    const head = addr.slice(0, dbl);
    const tail = addr.slice(dbl + 2);
    const h = head === "" ? [] : head.split(":");
    const t = tail === "" ? [] : tail.split(":");

    if (!h.every((g) => HEX_GROUP.test(g))) return null;
    if (!t.every((g) => HEX_GROUP.test(g))) return null;

    // "::" must stand for at least one zero group.
    if (h.length + t.length > 7) return null;

    const out: number[] = new Array(8).fill(0);
    h.forEach((g, i) => {
      out[i] = parseInt(g, 16);
    });
    t.forEach((g, i) => {
      out[8 - t.length + i] = parseInt(g, 16);
    });
    return out;
  }

  const groups = addr.split(":");
  if (groups.length !== 8) return null;
  if (!groups.every((g) => HEX_GROUP.test(g))) return null;
  return groups.map((g) => parseInt(g, 16));
}

function isIPv6(text: string): boolean {
  let addr = text;
  let zone: string | null = null;

  const pct = text.indexOf("%");
  if (pct !== -1) {
    addr = text.slice(0, pct);
    zone = text.slice(pct + 1);
    if (!ZONE_ID.test(zone)) return false;
  }

  const groups = parseIPv6(addr);
  if (groups === null) return false;

  // A zone index is only allowed on link-local addresses (fe80::/10).
  if (zone !== null && (groups[0] & 0xffc0) !== 0xfe80) return false;

  return true;
}

export function solve(text: string, version?: 4 | 6): boolean {
  const wantV4 = version === undefined || version === 4;
  const wantV6 = version === undefined || version === 6;

  if (wantV4 && isIPv4(text)) return true;
  if (wantV6 && isIPv6(text)) return true;
  return false;
}

export function solve(mac: string): boolean {
  const H2 = "[0-9a-fA-F]{2}";
  const H4 = "[0-9a-fA-F]{4}";

  const patterns: RegExp[] = [
    // EUI-48: six octets, consistent ':' or '-' separator (\1 forces the same one)
    new RegExp(`^${H2}([:-])${H2}(?:\\1${H2}){4}$`),
    // EUI-64: eight octets, consistent ':' or '-' separator
    new RegExp(`^${H2}([:-])${H2}(?:\\1${H2}){6}$`),
    // Dotted form: three groups of four hex digits
    new RegExp(`^(?:${H4}\\.){2}${H4}$`),
    // Dotted form: four groups of four hex digits
    new RegExp(`^(?:${H4}\\.){3}${H4}$`),
  ];

  return patterns.some((p) => p.test(mac));
}

export function solve(text: string): boolean {
  const m = /^(\()?([+-]?\d+(?:\.\d+)?),[ ]*([+-]?\d+(?:\.\d+)?)(\))?$/.exec(text);
  if (m === null) return false;

  const open = m[1];
  const lat = m[2];
  const lng = m[3];
  const close = m[4];

  // Parentheses must be either both present or both absent.
  if (Boolean(open) !== Boolean(close)) return false;

  return withinLimit(lat, 90) && withinLimit(lng, 180);
}

// Exact check that |value| <= limit, using string comparison to avoid
// floating-point issues with long fractional parts.
function withinLimit(value: string, limit: number): boolean {
  const unsigned = value.replace(/^[+-]/, '');
  const [intPart, fracPart = ''] = unsigned.split('.');
  const normInt = intPart.replace(/^0+/, '');
  const limitStr = String(limit);

  if (normInt.length !== limitStr.length) {
    return normInt.length < limitStr.length;
  }
  if (normInt !== limitStr) {
    return normInt < limitStr;
  }
  // Integer part equals the limit: only exact equality (zero fraction) is allowed.
  return /^0*$/.test(fracPart);
}

export function solve(code: string): boolean {
  if (typeof code !== "string") return false;
  if (!/^[0-9]+$/.test(code)) return false;

  const len = code.length;
  if (len !== 8 && len !== 13 && len !== 14) return false;

  // Weights alternate 3,1,3,1,... starting from the rightmost data digit
  // (the digit just left of the check digit).
  let sum = 0;
  for (let i = 0; i < len - 1; i++) {
    const digit = code.charCodeAt(i) - 48;
    const posFromRight = len - 2 - i;
    const weight = posFromRight % 2 === 0 ? 3 : 1;
    sum += digit * weight;
  }

  const check = (10 - (sum % 10)) % 10;
  return check === code.charCodeAt(len - 1) - 48;
}

export function solve(issn: string): boolean {
  if (!/^\d{4}-?\d{3}[\dXx]$/.test(issn)) {
    return false;
  }

  const chars = issn.replace("-", "");

  let sum = 0;
  for (let i = 0; i < 7; i++) {
    sum += (8 - i) * (chars.charCodeAt(i) - 48);
  }

  const last = chars[7];
  const check = last === "X" || last === "x" ? 10 : last.charCodeAt(0) - 48;
  sum += check;

  return sum % 11 === 0;
}

export function solve(doc: unknown, pointer: string): unknown {
  if (pointer === "") {
    return doc;
  }
  if (!pointer.startsWith("/")) {
    throw new Error(`Invalid JSON Pointer: must be empty or start with "/": ${pointer}`);
  }

  const tokens = pointer.slice(1).split("/");
  let current: unknown = doc;

  for (const raw of tokens) {
    // RFC 6901 order: decode ~1 to "/" first, then ~0 to "~".
    const token = raw.replace(/~1/g, "/").replace(/~0/g, "~");

    if (Array.isArray(current)) {
      // Array index: "0" or a non-zero-leading digit string. "-" is never a valid existing index.
      if (!/^(0|[1-9]\d*)$/.test(token)) {
        return undefined;
      }
      const index = Number(token);
      if (index >= current.length) {
        return undefined;
      }
      current = current[index];
    } else if (typeof current === "object" && current !== null) {
      if (!Object.prototype.hasOwnProperty.call(current, token)) {
        return undefined;
      }
      current = (current as Record<string, unknown>)[token];
    } else {
      // Cannot descend into primitives or null.
      return undefined;
    }
  }

  return current;
}

export function solve(a: string, b: string): number {
  const n = a.length;
  const m = b.length;
  if (n === 0) return m;
  if (m === 0) return n;

  let prev = new Array<number>(m + 1);
  let curr = new Array<number>(m + 1);
  for (let j = 0; j <= m; j++) prev[j] = j;

  for (let i = 1; i <= n; i++) {
    curr[0] = i;
    const ca = a.charCodeAt(i - 1);
    for (let j = 1; j <= m; j++) {
      const cost = ca === b.charCodeAt(j - 1) ? 0 : 1;
      let v = prev[j - 1] + cost;
      const del = prev[j] + 1;
      if (del < v) v = del;
      const ins = curr[j - 1] + 1;
      if (ins < v) v = ins;
      curr[j] = v;
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }

  return prev[m];
}

export function solve(isin: string): boolean {
  // Format: 2 uppercase letters, 9 uppercase alphanumerics, 1 digit check digit
  if (!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin)) {
    return false;
  }

  // Convert letters to numbers (A=10 ... Z=35), keeping digits as-is
  let digits = "";
  for (const ch of isin) {
    if (ch >= "A" && ch <= "Z") {
      digits += String(ch.charCodeAt(0) - 55);
    } else {
      digits += ch;
    }
  }

  // Luhn check over the full digit string, scanning from the rightmost digit.
  // Every second digit (starting with the second from the right) is doubled.
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48;
    if (double) {
      d *= 2;
      if (d > 9) {
        d -= 9;
      }
    }
    sum += d;
    double = !double;
  }

  return sum % 10 === 0;
}

export function solve(word: string, dictionary: string[]): string {
  // Compare by Unicode code points so that each character (including
  // astral-plane characters such as emoji) counts as one symbol.
  const source = Array.from(word);

  // Stays "" only when the dictionary is empty.
  let best = "";
  let bestDistance = Infinity;

  for (const entry of dictionary) {
    if (bestDistance === 0) break; // an exact match cannot be beaten

    const target = Array.from(entry);

    // The distance is at least the difference in lengths, so this entry
    // cannot strictly beat the current best. Skip the full computation.
    if (Math.abs(source.length - target.length) >= bestDistance) continue;

    const distance = levenshtein(source, target);

    // Strict "<" keeps the earliest entry when distances tie.
    if (distance < bestDistance) {
      bestDistance = distance;
      best = entry;
    }
  }

  return best;
}

// Levenshtein distance between two symbol sequences, using two rolling rows.
function levenshtein(a: string[], b: string[]): number {
  // The distance is symmetric; keep `b` as the shorter sequence to save memory.
  if (a.length < b.length) {
    [a, b] = [b, a];
  }

  const n = b.length;
  let prev = Array.from({ length: n + 1 }, (_, j) => j); // D[0][j] = j
  let curr = new Array<number>(n + 1).fill(0);

  for (let i = 1; i <= a.length; i++) {
    curr[0] = i;
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(
        prev[j] + 1, // delete a[i-1]
        curr[j - 1] + 1, // insert b[j-1]
        prev[j - 1] + cost, // substitute, or match when cost is 0
      );
    }
    [prev, curr] = [curr, prev];
  }

  return prev[n];
}

/**
 * Topologically sorts `nodes` so that for every edge [a, b], `a` appears before `b`.
 * Ties are broken by original position in `nodes`, so the result is the
 * lexicographically smallest valid order by position.
 *
 * @throws Error if `nodes` contains duplicates, an edge mentions a node not in `nodes`,
 *         or the edges contain a cycle (including self-loops).
 */
export function solve(nodes: string[], edges: [string, string][]): string[] {
  // Map every node name to its position in `nodes`.
  const position = new Map<string, number>();
  nodes.forEach((name, i) => {
    if (position.has(name)) {
      throw new Error(`Duplicate node "${name}"`);
    }
    position.set(name, i);
  });

  const n = nodes.length;
  const successors: number[][] = nodes.map((): number[] => []);
  const inDegree: number[] = new Array<number>(n).fill(0);

  for (const [from, to] of edges) {
    const u = position.get(from);
    const v = position.get(to);
    if (u === undefined || v === undefined) {
      const unknown = u === undefined ? from : to;
      throw new Error(`Edge [${from}, ${to}] mentions unknown node "${unknown}"`);
    }
    successors[u].push(v);
    inDegree[v] += 1;
  }

  // Min-heap of node positions: among all nodes whose prerequisites are
  // satisfied, always take the one that appears earliest in `nodes`.
  const heap: number[] = [];

  const heapPush = (value: number): void => {
    heap.push(value);
    let i = heap.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent] <= heap[i]) break;
      [heap[parent], heap[i]] = [heap[i], heap[parent]];
      i = parent;
    }
  };

  const heapPop = (): number => {
    const top = heap[0];
    const last = heap.pop() as number;
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      while (true) {
        const left = 2 * i + 1;
        const right = left + 1;
        let smallest = i;
        if (left < heap.length && heap[left] < heap[smallest]) smallest = left;
        if (right < heap.length && heap[right] < heap[smallest]) smallest = right;
        if (smallest === i) break;
        [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
        i = smallest;
      }
    }
    return top;
  };

  for (let i = 0; i < n; i++) {
    if (inDegree[i] === 0) heapPush(i);
  }

  const result: string[] = [];
  while (heap.length > 0) {
    const u = heapPop();
    result.push(nodes[u]);
    for (const v of successors[u]) {
      inDegree[v] -= 1;
      if (inDegree[v] === 0) heapPush(v);
    }
  }

  if (result.length !== n) {
    const stuck = nodes.filter((_, i) => inDegree[i] > 0);
    throw new Error(`Cycle detected; cannot order nodes: ${stuck.join(", ")}`);
  }

  return result;
}

const ALPHABET =
  "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const PAD = "=";

// Returns the 6-bit value of the base64 character at `index`.
function sextet(text: string, index: number): number {
  const ch = text.charAt(index);
  const value = ALPHABET.indexOf(ch);
  if (value === -1) {
    throw new Error(
      `Invalid base64 character ${JSON.stringify(ch)} at index ${index}`
    );
  }
  return value;
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error(
      `Invalid base64 length ${text.length}: must be a multiple of 4`
    );
  }

  const bytes: number[] = [];

  for (let i = 0; i < text.length; i += 4) {
    const isLastQuad = i + 4 === text.length;

    // The first two characters of every quad must be data characters.
    const s0 = sextet(text, i);
    const s1 = sextet(text, i + 1);
    let s2 = 0;
    let s3 = 0;
    let padding = 0; // number of '=' characters in this quad

    if (text.charAt(i + 2) === PAD) {
      // "xx==" encodes 1 byte; padding is only legal in the final quad.
      if (!isLastQuad || text.charAt(i + 3) !== PAD) {
        throw new Error(`Misplaced base64 padding at index ${i + 2}`);
      }
      padding = 2;
    } else {
      s2 = sextet(text, i + 2);
      if (text.charAt(i + 3) === PAD) {
        // "xxx=" encodes 2 bytes; padding is only legal in the final quad.
        if (!isLastQuad) {
          throw new Error(`Misplaced base64 padding at index ${i + 3}`);
        }
        padding = 1;
      } else {
        s3 = sextet(text, i + 3);
      }
    }

    // Combine four 6-bit values into one 24-bit group and emit its bytes.
    const group = (s0 << 18) | (s1 << 12) | (s2 << 6) | s3;

    bytes.push((group >> 16) & 0xff);
    if (padding < 2) {
      bytes.push((group >> 8) & 0xff);
    }
    if (padding < 1) {
      bytes.push(group & 0xff);
    }
  }

  return bytes;
}

export function solve(epochMs: number): string {
  // Floor before converting: Date's time clip truncates toward zero, so a
  // negative fractional instant would land in the wrong second.
  // e.g. -1000.5 ms is 1969-12-31T23:59:58.9995Z and must format as ...:58Z.
  const wholeMs = Math.floor(epochMs);

  // toISOString() is always UTC and always yields "YYYY-MM-DDTHH:mm:ss.sssZ"
  // (signed, expanded year outside 0000-9999). Drop the ".sss" part.
  // It throws a RangeError for NaN, +/-Infinity, or values outside the
  // +/-8.64e15 ms Date range.
  return new Date(wholeMs).toISOString().replace(/\.\d{3}Z$/, "Z");
}

// Encodes a string as UTF-8 bytes. Lone surrogates become U+FFFD (as TextEncoder does).
function utf8Encode(text: string): number[] {
  const out: number[] = [];
  for (let i = 0; i < text.length; i++) {
    let cp = text.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff) {
      // High surrogate: combine with a following low surrogate if present.
      const next = i + 1 < text.length ? text.charCodeAt(i + 1) : 0;
      if (next >= 0xdc00 && next <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
        i++;
      } else {
        cp = 0xfffd;
      }
    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
      cp = 0xfffd; // Lone low surrogate.
    }

    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }
  return out;
}

// SHA-1 (FIPS 180-4) over raw bytes; returns 40 lowercase hex digits.
function sha1Hex(input: number[]): string {
  // Padding (FIPS 180-4 §5.1.1): append 0x80, zero-fill to 56 (mod 64),
  // then append the 64-bit big-endian message length in bits.
  const msg = input.slice();
  const bitLength = input.length * 8;
  msg.push(0x80);
  while (msg.length % 64 !== 56) msg.push(0x00);
  const bitsHigh = Math.floor(bitLength / 0x100000000);
  const bitsLow = bitLength >>> 0;
  for (let s = 24; s >= 0; s -= 8) msg.push((bitsHigh >>> s) & 0xff);
  for (let s = 24; s >= 0; s -= 8) msg.push((bitsLow >>> s) & 0xff);

  // Initial hash value (§5.3.1).
  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  const w: number[] = new Array<number>(80);

  // Compression over each 512-bit block (§6.1.2).
  for (let off = 0; off < msg.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const j = off + 4 * t;
      w[t] = (msg[j] << 24) | (msg[j + 1] << 16) | (msg[j + 2] << 8) | msg[j + 3];
    }
    for (let t = 16; t < 80; t++) {
      const x = w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16];
      w[t] = (x << 1) | (x >>> 31);
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let t = 0; t < 80; t++) {
      let f: number;
      let k: number;
      if (t < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (t < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (t < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const temp = (((a << 5) | (a >>> 27)) + f + e + k + w[t]) >>> 0;
      e = d;
      d = c;
      c = (b << 30) | (b >>> 2);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
  }

  const hex8 = (v: number): string => ("00000000" + (v >>> 0).toString(16)).slice(-8);
  return hex8(h0) + hex8(h1) + hex8(h2) + hex8(h3) + hex8(h4);
}

export function solve(text: string): string {
  return sha1Hex(utf8Encode(text));
}

// Official SemVer 2.0.0 grammar; group 4 captures the prerelease, if any.
const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*)?$/;

interface ParsedVersion {
  raw: string;
  major: string;
  minor: string;
  patch: string;
  pre: string[] | null; // null for a release (no prerelease)
}

function parse(raw: string): ParsedVersion | null {
  const m = SEMVER_RE.exec(raw);
  if (m === null) return null;
  const pre: string | undefined = m[4];
  return {
    raw,
    major: m[1],
    minor: m[2],
    patch: m[3],
    pre: pre === undefined ? null : pre.split("."),
  };
}

// Numeric comparison of canonical digit strings (no leading zeros, any length).
function compareNumeric(a: string, b: string): number {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  return a === b ? 0 : a < b ? -1 : 1;
}

// Precedence of a single prerelease identifier.
function compareIdentifier(a: string, b: string): number {
  const aNumeric = /^\d+$/.test(a);
  const bNumeric = /^\d+$/.test(b);
  if (aNumeric && bNumeric) return compareNumeric(a, b);
  if (aNumeric !== bNumeric) return aNumeric ? -1 : 1; // numeric < alphanumeric
  return a === b ? 0 : a < b ? -1 : 1; // ASCII (code unit) order
}

// Precedence of prerelease identifier lists; a release (null) outranks any prerelease.
function comparePrerelease(a: string[] | null, b: string[] | null): number {
  if (a === null || b === null) {
    if (a === b) return 0;
    return a === null ? 1 : -1;
  }
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const c = compareIdentifier(a[i], b[i]);
    if (c !== 0) return c;
  }
  return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
}

// Full ordering: precedence first; equal precedence falls back to the full string.
function compareVersions(a: ParsedVersion, b: ParsedVersion): number {
  return (
    compareNumeric(a.major, b.major) ||
    compareNumeric(a.minor, b.minor) ||
    compareNumeric(a.patch, b.patch) ||
    comparePrerelease(a.pre, b.pre) ||
    (a.raw < b.raw ? -1 : a.raw > b.raw ? 1 : 0)
  );
}

export function solve(versions: string[]): string[] {
  return versions
    .map(parse)
    .filter((v): v is ParsedVersion => v !== null)
    .sort(compareVersions)
    .map((v) => v.raw);
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  if (typeof isbn !== "string") return false;

  // Spaces and hyphens are ignored.
  const s = isbn.replace(/[ -]/g, "");

  const acceptTen = version === undefined || version === 10;
  const acceptThirteen = version === undefined || version === 13;

  return (acceptTen && isValidIsbn10(s)) || (acceptThirteen && isValidIsbn13(s));
}

// ISBN-10: 9 digits followed by a digit or 'X' (= 10).
// Sum over 0-based i = 0..9 of (10 - i) * d[i] must be = 0 mod 11.
function isValidIsbn10(s: string): boolean {
  if (!/^\d{9}[\dX]$/.test(s)) return false;

  let sum = 0;
  for (let i = 0; i < 10; i++) {
    const c = s.charAt(i);
    const digit = c === "X" ? 10 : Number(c);
    sum += (10 - i) * digit;
  }
  return sum % 11 === 0;
}

// ISBN-13: 13 digits. Weights alternate 1, 3, 1, 3, ... starting at the first digit.
// Weighted sum must be = 0 mod 10.
function isValidIsbn13(s: string): boolean {
  if (!/^\d{13}$/.test(s)) return false;

  let sum = 0;
  for (let i = 0; i < 13; i++) {
    const digit = Number(s.charAt(i));
    sum += i % 2 === 0 ? digit : 3 * digit;
  }
  return sum % 10 === 0;
}

export function solve(isin: string): boolean {
  // Format: 2 upper-case letters, 9 upper-case alphanumerics, 1 check digit
  if (typeof isin !== "string" || !/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin)) {
    return false;
  }

  // Convert letters to numbers: A = 10, B = 11, ..., Z = 35
  const digits = isin.replace(/[A-Z]/g, (c) => String(c.charCodeAt(0) - 55));

  // Luhn algorithm over the full digit string, check digit included:
  // scanning from the right, double every second digit (subtracting 9 if > 9)
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48; // '0' is char code 48
    if (double) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    double = !double;
  }

  return sum % 10 === 0;
}

export function solve(code: string): boolean {
  // Must be a string consisting only of ASCII digits.
  if (typeof code !== "string" || !/^[0-9]+$/.test(code)) return false;

  // Valid EAN-8, EAN-13 and GTIN-14 lengths only.
  const n = code.length;
  if (n !== 8 && n !== 13 && n !== 14) return false;

  const digits = code.split("").map(Number);
  const check = digits[n - 1];

  // Weights alternate 3,1,3,1,... starting at the rightmost data digit
  // (the digit immediately left of the check digit) and moving left.
  let sum = 0;
  let weight = 3;
  for (let i = n - 2; i >= 0; i--) {
    sum += digits[i] * weight;
    weight = weight === 3 ? 1 : 3;
  }

  const expected = (10 - (sum % 10)) % 10;
  return check === expected;
}

export function solve(issn: string): boolean {
  // Accept exactly NNNN-NNNC or NNNNNNNC, where C is a digit or X/x.
  if (!/^\d{4}-?\d{3}[\dXx]$/.test(issn)) {
    return false;
  }

  // Remove the optional hyphen, leaving 8 characters.
  const s = issn.replace("-", "");

  // Weighted sum of the first seven digits (0-based index i, weight 8 - i).
  let sum = 0;
  for (let i = 0; i < 7; i++) {
    sum += (8 - i) * (s.charCodeAt(i) - 48); // 48 is the char code of '0'
  }

  // Check character: 'X' or 'x' stands for 10, otherwise its digit value.
  const check = s.charAt(7);
  sum += (check === "X" || check === "x") ? 10 : check.charCodeAt(0) - 48;

  return sum % 11 === 0;
}

// EUI-48 / EUI-64 in octet form: 6 or 8 octets of two hex digits.
// The first separator is captured and every later separator must match it
// (via \1), so ':' and '-' cannot be mixed.
const OCTETS_EUI48 = /^[0-9A-Fa-f]{2}([:-])(?:[0-9A-Fa-f]{2}\1){4}[0-9A-Fa-f]{2}$/;
const OCTETS_EUI64 = /^[0-9A-Fa-f]{2}([:-])(?:[0-9A-Fa-f]{2}\1){6}[0-9A-Fa-f]{2}$/;

// Dotted form: 3 (EUI-48) or 4 (EUI-64) groups of four hex digits.
const DOTTED_EUI48 = /^(?:[0-9A-Fa-f]{4}\.){2}[0-9A-Fa-f]{4}$/;
const DOTTED_EUI64 = /^(?:[0-9A-Fa-f]{4}\.){3}[0-9A-Fa-f]{4}$/;

export function solve(mac: string): boolean {
  return (
    OCTETS_EUI48.test(mac) ||
    OCTETS_EUI64.test(mac) ||
    DOTTED_EUI48.test(mac) ||
    DOTTED_EUI64.test(mac)
  );
}

/** Inclusive range of issuer prefixes. Both bounds have the same number of digits. */
type PrefixRange = readonly [string, string];

interface IssuerRule {
  readonly prefixes: readonly PrefixRange[];
  readonly lengths: readonly number[];
}

const ISSUERS: readonly IssuerRule[] = [
  // Visa: starts with 4; 13, 16 or 19 digits
  { prefixes: [["4", "4"]], lengths: [13, 16, 19] },

  // Mastercard: 51-55 or 2221-2720; 16 digits
  { prefixes: [["51", "55"], ["2221", "2720"]], lengths: [16] },

  // American Express: 34 or 37; 15 digits
  { prefixes: [["34", "34"], ["37", "37"]], lengths: [15] },

  // Discover: 6011, 622126-622925, 644-649, 65; 16 or 19 digits
  {
    prefixes: [["6011", "6011"], ["622126", "622925"], ["644", "649"], ["65", "65"]],
    lengths: [16, 19],
  },

  // Diners Club: 300-305, 36, 38; 14-19 digits
  {
    prefixes: [["300", "305"], ["36", "36"], ["38", "38"]],
    lengths: [14, 15, 16, 17, 18, 19],
  },

  // JCB: 3528-3589; 16-19 digits
  { prefixes: [["3528", "3589"]], lengths: [16, 17, 18, 19] },

  // UnionPay: 62; 16-19 digits
  { prefixes: [["62", "62"]], lengths: [16, 17, 18, 19] },
];

/**
 * True if the leading digits of `digits` fall within the inclusive range [lo, hi].
 * Bounds have equal width, so string comparison matches numeric comparison.
 */
function prefixInRange(digits: string, [lo, hi]: PrefixRange): boolean {
  const prefix = digits.slice(0, lo.length);
  return prefix.length === lo.length && prefix >= lo && prefix <= hi;
}

/** Luhn (mod 10) checksum for a string of decimal digits. */
function passesLuhn(digits: string): boolean {
  let sum = 0;
  let doubleDigit = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = Number(digits[i]);
    if (doubleDigit) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    doubleDigit = !doubleDigit;
  }
  return sum % 10 === 0;
}

export function solve(card: string): boolean {
  const digits = card.replace(/[\s-]/g, "");
  if (!/^\d+$/.test(digits)) return false;

  const issuerMatch = ISSUERS.some(
    ({ prefixes, lengths }) =>
      lengths.indexOf(digits.length) !== -1 &&
      prefixes.some((range) => prefixInRange(digits, range))
  );

  return issuerMatch && passesLuhn(digits);
}

export function solve(a: string, b: string): number {
  // Use the shorter string as the row dimension to keep memory at O(min(|a|, |b|)).
  let longer = a;
  let shorter = b;
  if (longer.length < shorter.length) {
    longer = b;
    shorter = a;
  }

  const n = shorter.length;
  if (n === 0) {
    return longer.length;
  }

  // UTF-16 code units of the shorter string.
  const s = new Uint16Array(n);
  for (let j = 0; j < n; j++) {
    s[j] = shorter.charCodeAt(j);
  }

  let prev = new Uint32Array(n + 1); // DP row for i - 1
  let curr = new Uint32Array(n + 1); // DP row for i
  for (let j = 0; j <= n; j++) {
    prev[j] = j;
  }

  for (let i = 1; i <= longer.length; i++) {
    const c = longer.charCodeAt(i - 1);
    curr[0] = i;
    for (let j = 1; j <= n; j++) {
      const cost = c === s[j - 1] ? 0 : 1;
      curr[j] = Math.min(
        prev[j - 1] + cost, // match or substitution
        prev[j] + 1,        // deletion
        curr[j - 1] + 1     // insertion
      );
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }

  return prev[n];
}

export function solve(doc: unknown, pointer: string): unknown {
  // The empty pointer refers to the whole document.
  if (pointer === "") {
    return doc;
  }

  if (!pointer.startsWith("/")) {
    throw new Error(`Invalid JSON Pointer "${pointer}": must be empty or start with "/"`);
  }

  // Drop the leading "/" and split the rest; each piece is one reference token (possibly empty).
  const tokens = pointer.slice(1).split("/");
  let current: unknown = doc;

  for (const encoded of tokens) {
    // RFC 6901 unescaping: "~1" -> "/" must happen before "~0" -> "~".
    const token = encoded.replace(/~1/g, "/").replace(/~0/g, "~");

    if (Array.isArray(current)) {
      // Array index: "0" or a digit string without leading zeros.
      // Anything else, including "-" (the nonexistent slot past the end), is absent.
      if (!/^(0|[1-9][0-9]*)$/.test(token)) {
        return undefined;
      }
      const index = Number(token);
      if (index >= current.length) {
        return undefined;
      }
      current = current[index];
    } else if (typeof current === "object" && current !== null) {
      // Only own properties count, so inherited names such as "constructor" are absent.
      if (!Object.prototype.hasOwnProperty.call(current, token)) {
        return undefined;
      }
      current = (current as Record<string, unknown>)[token];
    } else {
      // Primitives and null have no members to descend into.
      return undefined;
    }
  }

  return current;
}

export function solve(text: string): boolean {
  // Optional single pair of enclosing parentheses, only if both are present.
  const body =
    text.startsWith("(") && text.endsWith(")") ? text.slice(1, -1) : text;

  // latitude "," [spaces] longitude; each is [sign] digits ["." digits]
  const pair = /^([+-]?\d+(?:\.\d+)?), *([+-]?\d+(?:\.\d+)?)$/.exec(body);
  if (pair === null) {
    return false;
  }

  const [, lat = "", lon = ""] = pair;
  return withinBound(lat, 90) && withinBound(lon, 180);
}

// Exact check of |coord| <= bound (bound is a non-negative integer), done on the
// decimal text so floating-point rounding cannot pull values such as
// "90.00000000000000001" into range.
function withinBound(coord: string, bound: number): boolean {
  const [intPart = "", fracPart = ""] = coord.replace(/^[+-]/, "").split(".");
  const digits = intPart.replace(/^0+/, "");
  if (digits.length > String(bound).length) {
    return false;
  }
  const whole = digits === "" ? 0 : Number(digits);
  if (whole !== bound) {
    return whole < bound;
  }
  return /^0*$/.test(fracPart);
}

type Key = string | number;
type Container = Record<string | number, unknown>;

function parsePath(path: string): Key[] {
  const keys: Key[] = [];
  let buf = "";
  const flush = (): void => {
    if (buf !== "") {
      keys.push(buf);
      buf = "";
    }
  };

  let i = 0;
  while (i < path.length) {
    const c = path[i];
    if (c === ".") {
      flush();
      i++;
    } else if (c === "[") {
      flush();
      i++; // skip '['
      const q = path[i];
      if (q === '"' || q === "'") {
        i++; // skip opening quote
        let s = "";
        while (i < path.length && path[i] !== q) {
          if (path[i] === "\\" && i + 1 < path.length) {
            s += path[i + 1];
            i += 2;
          } else {
            s += path[i];
            i++;
          }
        }
        if (i >= path.length) throw new SyntaxError(`Unterminated quoted key in path: ${path}`);
        i++; // skip closing quote
        if (path[i] !== "]") throw new SyntaxError(`Expected ']' in path: ${path}`);
        i++;
        keys.push(s);
      } else {
        const end = path.indexOf("]", i);
        if (end === -1) throw new SyntaxError(`Unterminated '[' in path: ${path}`);
        const content = path.slice(i, end).trim();
        i = end + 1;
        keys.push(/^\d+$/.test(content) ? Number(content) : content);
      }
    } else {
      buf += c;
      i++;
    }
  }
  flush();
  return keys;
}

function isIndex(key: Key): boolean {
  if (typeof key === "number") return Number.isInteger(key) && key >= 0;
  return /^(0|[1-9]\d*)$/.test(key);
}

function assertSafeKey(key: Key): void {
  if (key === "__proto__") {
    throw new TypeError("Refusing to write to '__proto__'");
  }
}

export function solve(
  obj: object,
  updates: [string | (string | number)[], unknown][]
): object {
  for (const [path, value] of updates) {
    const keys: Key[] = typeof path === "string" ? parsePath(path) : path;
    if (keys.length === 0) continue;

    let cur = obj as Container;
    for (let i = 0; i < keys.length - 1; i++) {
      const key = keys[i];
      assertSafeKey(key);
      let next = cur[key] as unknown;
      if (typeof next !== "object" || next === null) {
        next = isIndex(keys[i + 1]) ? [] : {};
        cur[key] = next;
      }
      cur = next as Container;
    }

    const last = keys[keys.length - 1];
    assertSafeKey(last);
    cur[last] = value;
  }
  return obj;
}

export function solve(urls: string[]): string[] {
  // Scheme: http or https (case-insensitive).
  // Optional userinfo (no whitespace, no '@', '/', '?', '#' before the '@').
  // Host: one or more labels of letters/digits/hyphens (no leading or trailing hyphen),
  //       followed by a TLD that is alphabetic (2-63 chars) or a punycode "xn--" label.
  //       IP addresses are rejected because the TLD must contain letters.
  // Optional port of 1-5 digits (range checked separately).
  // Optional path, query, or fragment with no whitespace.
  const pattern =
    /^https?:\/\/(?:[^\s@/?#]+@)?((?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+(?:[a-z]{2,63}|xn--[a-z0-9-]{1,59}[a-z0-9]))(?::(\d{1,5}))?(?:[/?#]\S*)?$/i;

  const result: string[] = [];

  for (const url of urls) {
    const match = pattern.exec(url);
    if (!match) continue;

    const host = match[1];
    const port = match[2];

    if (host.length > 253) continue;
    if (port !== undefined && Number(port) > 65535) continue;

    result.push(url);
  }

  return result;
}

export function solve(word: string, dictionary: string[]): string {
  if (dictionary.length === 0) return "";

  let best = dictionary[0];
  let bestDist = levenshtein(word, best);

  for (let i = 1; i < dictionary.length; i++) {
    if (bestDist === 0) break; // exact match found; the first one already wins ties
    const d = levenshtein(word, dictionary[i]);
    if (d < bestDist) {
      bestDist = d;
      best = dictionary[i];
    }
  }

  return best;
}

function levenshtein(a: string, b: string): number {
  if (a === b) return 0;
  const m = a.length;
  const n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;

  let prev: number[] = new Array<number>(n + 1);
  let curr: number[] = new Array<number>(n + 1);

  for (let j = 0; j <= n; j++) prev[j] = j;

  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(
        prev[j] + 1,        // deletion
        curr[j - 1] + 1,    // insertion
        prev[j - 1] + cost  // substitution (or match)
      );
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }

  return prev[n];
}

type Seen = Map<object, unknown>;

function cloneValue(input: unknown, seen: Seen): unknown {
  // Primitives and functions are returned as-is.
  if (typeof input !== "object" || input === null) {
    return input;
  }

  // Already copied (or currently being copied): reuse the copy.
  // This is what preserves circular and shared references.
  if (seen.has(input)) {
    return seen.get(input);
  }

  if (input instanceof Date) {
    const copy = new Date(input.getTime());
    seen.set(input, copy);
    return copy;
  }

  if (input instanceof RegExp) {
    const copy = new RegExp(input.source, input.flags);
    copy.lastIndex = input.lastIndex;
    seen.set(input, copy);
    return copy;
  }

  if (input instanceof Map) {
    const copy = new Map<unknown, unknown>();
    seen.set(input, copy); // register before recursing to handle cycles
    input.forEach((v, k) => {
      copy.set(cloneValue(k, seen), cloneValue(v, seen));
    });
    return copy;
  }

  if (input instanceof Set) {
    const copy = new Set<unknown>();
    seen.set(input, copy);
    input.forEach((v) => {
      copy.add(cloneValue(v, seen));
    });
    return copy;
  }

  if (input instanceof ArrayBuffer) {
    const copy = input.slice(0);
    seen.set(input, copy);
    return copy;
  }

  if (ArrayBuffer.isView(input)) {
    const source = input as ArrayBufferView;
    const srcBuffer = source.buffer;

    // Shared buffers stay shared by definition; regular buffers are copied once
    // and reused by every view that references them.
    const buffer: ArrayBuffer =
      srcBuffer instanceof ArrayBuffer
        ? (cloneValue(srcBuffer, seen) as ArrayBuffer)
        : (srcBuffer as ArrayBuffer);

    if (source instanceof DataView) {
      const copy = new DataView(buffer, source.byteOffset, source.byteLength);
      seen.set(input, copy);
      return copy;
    }

    const Ctor = source.constructor as new (
      buffer: ArrayBuffer,
      byteOffset: number,
      length: number
    ) => ArrayBufferView;
    const length = (source as unknown as { length: number }).length;
    const copy = new Ctor(buffer, source.byteOffset, length);
    seen.set(input, copy);
    return copy;
  }

  if (Array.isArray(input)) {
    const copy: unknown[] = new Array(input.length);
    seen.set(input, copy);
    copyOwnProperties(input, copy, seen, ["length"]);
    return copy;
  }

  // Plain objects and class instances: keep the prototype, copy own properties.
  const copy = Object.create(Object.getPrototypeOf(input)) as object;
  seen.set(input, copy);
  copyOwnProperties(input, copy, seen, []);
  return copy;
}

function copyOwnProperties(
  source: object,
  target: object,
  seen: Seen,
  skip: PropertyKey[]
): void {
  for (const key of Reflect.ownKeys(source)) {
    if (skip.includes(key)) {
      continue;
    }
    const descriptor = Object.getOwnPropertyDescriptor(source, key);
    if (!descriptor) {
      continue;
    }
    if ("value" in descriptor) {
      descriptor.value = cloneValue(descriptor.value, seen);
    }
    Object.defineProperty(target, key, descriptor);
  }
}

export function solve<T>(value: T): T {
  return cloneValue(value, new Map()) as T;
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  const index = new Map<string, number>();
  nodes.forEach((name, i) => {
    if (index.has(name)) {
      throw new Error(`Duplicate node: ${name}`);
    }
    index.set(name, i);
  });

  const n = nodes.length;
  const adj: number[][] = Array.from({ length: n }, () => [] as number[]);
  const indegree: number[] = new Array<number>(n).fill(0);

  for (const [a, b] of edges) {
    const ia = index.get(a);
    const ib = index.get(b);
    if (ia === undefined) {
      throw new Error(`Edge references unknown node: ${a}`);
    }
    if (ib === undefined) {
      throw new Error(`Edge references unknown node: ${b}`);
    }
    adj[ia].push(ib);
    indegree[ib]++;
  }

  // Min-heap of available node indices, so ties are broken by input order.
  const heap: number[] = [];

  const heapPush = (v: number): void => {
    heap.push(v);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p] <= heap[i]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };

  const heapPop = (): number => {
    const top = heap[0];
    const last = heap.pop() as number;
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1;
        const r = l + 1;
        let m = i;
        if (l < heap.length && heap[l] < heap[m]) m = l;
        if (r < heap.length && heap[r] < heap[m]) m = r;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]];
        i = m;
      }
    }
    return top;
  };

  for (let i = 0; i < n; i++) {
    if (indegree[i] === 0) heapPush(i);
  }

  const result: string[] = [];
  while (heap.length > 0) {
    const v = heapPop();
    result.push(nodes[v]);
    for (const w of adj[v]) {
      indegree[w]--;
      if (indegree[w] === 0) heapPush(w);
    }
  }

  if (result.length !== n) {
    throw new Error("Cycle detected in edges");
  }

  return result;
}

const BASE64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function base64Value(ch: string): number {
  const index = ch.length === 1 ? BASE64_ALPHABET.indexOf(ch) : -1;
  if (index < 0) {
    throw new Error(`Invalid base64 character: ${JSON.stringify(ch)}`);
  }
  return index;
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error("Invalid base64 length: must be a multiple of 4");
  }

  const bytes: number[] = [];

  for (let i = 0; i < text.length; i += 4) {
    const c0 = text.charAt(i);
    const c1 = text.charAt(i + 1);
    const c2 = text.charAt(i + 2);
    const c3 = text.charAt(i + 3);

    const isLastQuad = i + 4 === text.length;
    const pad2 = c2 === "=";
    const pad3 = c3 === "=";

    if ((pad2 || pad3) && !isLastQuad) {
      throw new Error("Invalid base64: padding found before end of input");
    }
    if (pad2 && !pad3) {
      throw new Error("Invalid base64: incorrect padding");
    }

    const v0 = base64Value(c0);
    const v1 = base64Value(c1);
    const v2 = pad2 ? 0 : base64Value(c2);
    const v3 = pad3 ? 0 : base64Value(c3);

    bytes.push(((v0 << 2) | (v1 >> 4)) & 0xff);

    if (!pad2) {
      bytes.push((((v1 & 0x0f) << 4) | (v2 >> 2)) & 0xff);
    }

    if (!pad3) {
      bytes.push((((v2 & 0x03) << 6) | v3) & 0xff);
    }
  }

  return bytes;
}

export function solve(name: string, namespace: string): string {
  // Parse the namespace UUID into 16 bytes.
  const nsHex = namespace.replace(/-/g, "");
  if (!/^[0-9a-fA-F]{32}$/.test(nsHex)) {
    throw new Error("invalid namespace UUID");
  }
  const nsBytes: number[] = [];
  for (let i = 0; i < 32; i += 2) {
    nsBytes.push(parseInt(nsHex.slice(i, i + 2), 16));
  }

  // UTF-8 encode the name manually (lone surrogates become U+FFFD).
  const nameBytes = utf8Encode(name);

  // Message = namespace bytes || name bytes.
  const msg = new Uint8Array(nsBytes.length + nameBytes.length);
  msg.set(nsBytes, 0);
  msg.set(nameBytes, nsBytes.length);

  // SHA-1 and truncate to 16 bytes.
  const digest = sha1(msg);
  const out = digest.slice(0, 16);

  // Set version (5) and RFC 4122 variant bits.
  out[6] = (out[6] & 0x0f) | 0x50;
  out[8] = (out[8] & 0x3f) | 0x80;

  // Format as lowercase 8-4-4-4-12.
  const hex: string[] = [];
  for (let i = 0; i < 16; i++) {
    hex.push(out[i].toString(16).padStart(2, "0"));
  }
  const s = hex.join("");
  return (
    s.slice(0, 8) + "-" +
    s.slice(8, 12) + "-" +
    s.slice(12, 16) + "-" +
    s.slice(16, 20) + "-" +
    s.slice(20, 32)
  );
}

function utf8Encode(str: string): number[] {
  const bytes: number[] = [];
  for (const ch of str) {
    let cp = ch.codePointAt(0) as number;
    if (cp >= 0xd800 && cp <= 0xdfff) {
      cp = 0xfffd;
    }
    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }
  return bytes;
}

function rotl(x: number, n: number): number {
  return ((x << n) | (x >>> (32 - n))) >>> 0;
}

function sha1(data: Uint8Array): Uint8Array {
  const bitLen = data.length * 8;
  const total = Math.ceil((data.length + 9) / 64) * 64;
  const buf = new Uint8Array(total);
  buf.set(data, 0);
  buf[data.length] = 0x80;

  // 64-bit big-endian message length in bits.
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  for (let i = 0; i < 4; i++) {
    buf[total - 8 + i] = (hi >>> (24 - 8 * i)) & 0xff;
    buf[total - 4 + i] = (lo >>> (24 - 8 * i)) & 0xff;
  }

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  const w = new Uint32Array(80);

  for (let off = 0; off < total; off += 64) {
    for (let i = 0; i < 16; i++) {
      const j = off + i * 4;
      w[i] =
        ((buf[j] << 24) | (buf[j + 1] << 16) | (buf[j + 2] << 8) | buf[j + 3]) >>> 0;
    }
    for (let i = 16; i < 80; i++) {
      w[i] = rotl(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let i = 0; i < 80; i++) {
      let f: number;
      let k: number;
      if (i < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (i < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (i < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const temp = (rotl(a, 5) + (f >>> 0) + e + k + w[i]) >>> 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
  }

  const out = new Uint8Array(20);
  const hs = [h0, h1, h2, h3, h4];
  for (let i = 0; i < 5; i++) {
    out[i * 4] = (hs[i] >>> 24) & 0xff;
    out[i * 4 + 1] = (hs[i] >>> 16) & 0xff;
    out[i * 4 + 2] = (hs[i] >>> 8) & 0xff;
    out[i * 4 + 3] = hs[i] & 0xff;
  }
  return out;
}

export function solve(epochMs: number): string {
  if (!Number.isFinite(epochMs)) {
    throw new RangeError("Invalid time value");
  }

  // Floor to an integer millisecond, then floor to a whole second using exact integer arithmetic.
  const whole = Math.floor(epochMs);
  const msPart = ((whole % 1000) + 1000) % 1000;
  const floored = whole - msPart;

  // toISOString always emits ".sssZ"; the milliseconds are now zero, so strip them.
  return new Date(floored).toISOString().replace(/\.000Z$/, "Z");
}

export function solve(text: string): string {
  // Encode the input as UTF-8 manually (lone surrogates become U+FFFD, as TextEncoder does).
  const bytes: number[] = [];
  for (const ch of text) {
    let cp = ch.codePointAt(0) as number;
    if (cp >= 0xd800 && cp <= 0xdfff) cp = 0xfffd;
    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  // Padding (RFC 1321 section 3.1 and 3.2)
  const origLen = bytes.length;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);

  const bitLo = (origLen * 8) >>> 0;
  const bitHi = Math.floor(origLen / 0x20000000) >>> 0;
  for (let i = 0; i < 4; i++) bytes.push((bitLo >>> (8 * i)) & 0xff);
  for (let i = 0; i < 4; i++) bytes.push((bitHi >>> (8 * i)) & 0xff);

  // Per-round shift amounts
  const S: number[] = [
    7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
    5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
    4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
    6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
  ];

  // K[i] = floor(|sin(i + 1)| * 2^32)
  const K: number[] = [];
  for (let i = 0; i < 64; i++) {
    K.push(Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296) >>> 0);
  }

  const rotl = (x: number, c: number): number => (x << c) | (x >>> (32 - c));

  let a0 = 0x67452301;
  let b0 = 0xefcdab89 | 0;
  let c0 = 0x98badcfe | 0;
  let d0 = 0x10325476;

  for (let off = 0; off < bytes.length; off += 64) {
    const M: number[] = new Array(16);
    for (let j = 0; j < 16; j++) {
      const p = off + 4 * j;
      M[j] =
        bytes[p] |
        (bytes[p + 1] << 8) |
        (bytes[p + 2] << 16) |
        (bytes[p + 3] << 24);
    }

    let A = a0;
    let B = b0;
    let C = c0;
    let D = d0;

    for (let i = 0; i < 64; i++) {
      let F: number;
      let g: number;
      if (i < 16) {
        F = (B & C) | (~B & D);
        g = i;
      } else if (i < 32) {
        F = (D & B) | (~D & C);
        g = (5 * i + 1) % 16;
      } else if (i < 48) {
        F = B ^ C ^ D;
        g = (3 * i + 5) % 16;
      } else {
        F = C ^ (B | ~D);
        g = (7 * i) % 16;
      }
      F = (F + A + K[i] + M[g]) | 0;
      A = D;
      D = C;
      C = B;
      B = (B + rotl(F, S[i])) | 0;
    }

    a0 = (a0 + A) | 0;
    b0 = (b0 + B) | 0;
    c0 = (c0 + C) | 0;
    d0 = (d0 + D) | 0;
  }

  // Output digest bytes in little-endian order for each word
  let out = "";
  for (const w of [a0, b0, c0, d0]) {
    for (let j = 0; j < 4; j++) {
      const byte = (w >>> (8 * j)) & 0xff;
      out += byte.toString(16).padStart(2, "0");
    }
  }
  return out;
}

const DAY_MS = 86_400_000;
const HOUR_MS = 3_600_000;
const MINUTE_MS = 60_000;

const PATTERN =
  /^(?:(\d{4})-(\d{2})-(\d{2})|(\d{4})-W(\d{2})-(\d)|(\d{4})-(\d{3}))(?:T(\d{2})(?::(\d{2})(?::(\d{2})(?:[.,](\d+))?)?)?(Z|[+-]\d{2}:\d{2})?)?$/;

const MONTH_DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeap(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, m: number): number {
  return m === 2 && isLeap(y) ? 29 : MONTH_DAYS[m - 1];
}

/** Monday-based weekday helper: 0 = Sunday for the p-function below. */
function p(y: number): number {
  const v = y + Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400);
  return ((v % 7) + 7) % 7;
}

function isoWeeksInYear(y: number): number {
  return p(y) === 4 || p(y - 1) === 3 ? 53 : 52;
}

/** Epoch ms of 00:00:00.000 UTC on the given calendar date (valid for all years). */
function utcMs(y: number, m: number, d: number): number {
  const dt = new Date(0);
  dt.setUTCFullYear(y, m - 1, d);
  return dt.getTime();
}

function parseOne(s: string): number {
  if (typeof s !== "string") {
    throw new RangeError(`Invalid ISO 8601 date: ${String(s)}`);
  }

  const m: (string | undefined)[] | null = PATTERN.exec(s);
  if (!m) {
    throw new RangeError(`Invalid ISO 8601 date: ${s}`);
  }

  const [
    , cy, cm, cd,
    wy, ww, wdStr,
    oy, od,
    hh, mi, ss, frac, off,
  ] = m;

  let base: number;

  if (cy !== undefined) {
    // Calendar date: YYYY-MM-DD
    const y = Number(cy);
    const mo = Number(cm);
    const d = Number(cd);
    if (mo < 1 || mo > 12 || d < 1 || d > daysInMonth(y, mo)) {
      throw new RangeError(`Invalid calendar date: ${s}`);
    }
    base = utcMs(y, mo, d);
  } else if (wy !== undefined) {
    // Week date: YYYY-Www-D
    const y = Number(wy);
    const w = Number(ww);
    const dow = Number(wdStr);
    if (w < 1 || w > isoWeeksInYear(y) || dow < 1 || dow > 7) {
      throw new RangeError(`Invalid week date: ${s}`);
    }
    // ISO week 1 is the week containing January 4th.
    const t4 = utcMs(y, 1, 4);
    const isoDow4 = ((new Date(t4).getUTCDay() + 6) % 7) + 1; // Mon=1..Sun=7
    const week1Monday = t4 - (isoDow4 - 1) * DAY_MS;
    base = week1Monday + ((w - 1) * 7 + (dow - 1)) * DAY_MS;
  } else {
    // Ordinal date: YYYY-DDD
    const y = Number(oy);
    const o = Number(od);
    const maxDay = isLeap(y) ? 366 : 365;
    if (o < 1 || o > maxDay) {
      throw new RangeError(`Invalid ordinal date: ${s}`);
    }
    base = utcMs(y, 1, 1) + (o - 1) * DAY_MS;
  }

  let t = base;

  if (hh !== undefined) {
    const h = Number(hh);
    const mn = mi === undefined ? 0 : Number(mi);
    const sec = ss === undefined ? 0 : Number(ss);
    const ms = frac === undefined ? 0 : parseInt((frac + "00").slice(0, 3), 10);
    const fracNonZero = frac !== undefined && /[1-9]/.test(frac);

    if (h === 24) {
      // ISO 8601 allows 24:00:00 meaning midnight at the end of the day.
      if (mn !== 0 || sec !== 0 || fracNonZero) {
        throw new RangeError(`Invalid time: ${s}`);
      }
    } else if (h > 23) {
      throw new RangeError(`Invalid time: ${s}`);
    }
    if (mn > 59 || sec > 59) {
      throw new RangeError(`Invalid time: ${s}`);
    }

    t += h * HOUR_MS + mn * MINUTE_MS + sec * 1000 + ms;

    if (off !== undefined && off !== "Z") {
      const sign = off[0] === "+" ? 1 : -1;
      const oh = Number(off.slice(1, 3));
      const om = Number(off.slice(4, 6));
      if (oh > 23 || om > 59) {
        throw new RangeError(`Invalid offset: ${s}`);
      }
      t -= sign * (oh * HOUR_MS + om * MINUTE_MS);
    }
  }

  if (!Number.isFinite(t)) {
    throw new RangeError(`Invalid ISO 8601 date: ${s}`);
  }
  return t;
}

export function solve(stamps: string[]): number[] {
  if (!Array.isArray(stamps)) {
    throw new RangeError("Input must be an array of strings");
  }
  return stamps.map(parseOne).sort((a, b) => a - b);
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

interface ParsedVersion {
  raw: string;
  major: string;
  minor: string;
  patch: string;
  pre: string[] | null;
}

function cmpNumericString(a: string, b: string): number {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

function cmpPreIdentifier(a: string, b: string): number {
  const aNum = /^\d+$/.test(a);
  const bNum = /^\d+$/.test(b);
  if (aNum && bNum) return cmpNumericString(a, b);
  if (aNum) return -1; // numeric identifiers have lower precedence
  if (bNum) return 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

function parse(v: string): ParsedVersion | null {
  const m = SEMVER_RE.exec(v);
  if (!m) return null;
  return {
    raw: v,
    major: m[1],
    minor: m[2],
    patch: m[3],
    pre: m[4] !== undefined ? m[4].split(".") : null,
  };
}

function compareVersions(a: ParsedVersion, b: ParsedVersion): number {
  let c = cmpNumericString(a.major, b.major);
  if (c !== 0) return c;
  c = cmpNumericString(a.minor, b.minor);
  if (c !== 0) return c;
  c = cmpNumericString(a.patch, b.patch);
  if (c !== 0) return c;

  // Prerelease: a version without prerelease has higher precedence.
  if (a.pre === null && b.pre === null) {
    // equal precedence; fall through to build-metadata tie-break
  } else if (a.pre === null) {
    return 1;
  } else if (b.pre === null) {
    return -1;
  } else {
    const len = Math.min(a.pre.length, b.pre.length);
    for (let i = 0; i < len; i++) {
      c = cmpPreIdentifier(a.pre[i], b.pre[i]);
      if (c !== 0) return c;
    }
    if (a.pre.length !== b.pre.length) {
      return a.pre.length < b.pre.length ? -1 : 1;
    }
  }

  // Equal precedence: order by full string lexically.
  return a.raw < b.raw ? -1 : a.raw > b.raw ? 1 : 0;
}

export function solve(versions: string[]): string[] {
  const parsed: ParsedVersion[] = [];
  for (const v of versions) {
    const p = parse(v);
    if (p !== null) parsed.push(p);
  }
  parsed.sort(compareVersions);
  return parsed.map((p) => p.raw);
}

export function solve(text: string): string {
  // Encode the string as UTF-8 manually (no TextEncoder, no Node/browser APIs).
  const bytes: number[] = [];
  for (let i = 0; i < text.length; i++) {
    let cp = text.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff) {
      // High surrogate: combine with a following low surrogate if present.
      const lo = i + 1 < text.length ? text.charCodeAt(i + 1) : 0;
      if (lo >= 0xdc00 && lo <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
        i++;
      } else {
        cp = 0xfffd; // unpaired surrogate
      }
    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
      cp = 0xfffd; // unpaired low surrogate
    }

    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  // Padding (FIPS 180-4, section 5.1.1).
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) {
    bytes.push(0);
  }
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  bytes.push(
    (hi >>> 24) & 0xff, (hi >>> 16) & 0xff, (hi >>> 8) & 0xff, hi & 0xff,
    (lo >>> 24) & 0xff, (lo >>> 16) & 0xff, (lo >>> 8) & 0xff, lo & 0xff
  );

  const rotl = (x: number, n: number): number => (x << n) | (x >>> (32 - n));

  // Initial hash values (section 5.3.1).
  let h0 = 0x67452301;
  let h1 = 0xefcdab89 | 0;
  let h2 = 0x98badcfe | 0;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0 | 0;

  const W: number[] = new Array(80);

  for (let off = 0; off < bytes.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const p = off + t * 4;
      W[t] =
        (bytes[p] << 24) |
        (bytes[p + 1] << 16) |
        (bytes[p + 2] << 8) |
        bytes[p + 3];
    }
    for (let t = 16; t < 80; t++) {
      W[t] = rotl(W[t - 3] ^ W[t - 8] ^ W[t - 14] ^ W[t - 16], 1);
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let t = 0; t < 80; t++) {
      let f: number;
      let k: number;
      if (t < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (t < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (t < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const temp = (rotl(a, 5) + f + e + k + W[t]) | 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) | 0;
    h1 = (h1 + b) | 0;
    h2 = (h2 + c) | 0;
    h3 = (h3 + d) | 0;
    h4 = (h4 + e) | 0;
  }

  const hex = (x: number): string => (x >>> 0).toString(16).padStart(8, "0");
  return hex(h0) + hex(h1) + hex(h2) + hex(h3) + hex(h4);
}

type Parsed = {
  core: [string, string, string];
  pre: string[] | null;
};

const SEMVER =
  /^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$/;

function parse(v: string): Parsed {
  const m = SEMVER.exec(v);
  if (!m) throw new TypeError(`Invalid semver version: ${JSON.stringify(v)}`);
  return {
    core: [m[1], m[2], m[3]],
    pre: m[4] === undefined ? null : m[4].split("."),
  };
}

// Compare numeric identifiers (no leading zeros in valid semver) without precision loss.
function cmpNum(a: string, b: string): number {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

// Compare a single prerelease identifier per semver precedence rules.
function cmpPreId(x: string, y: string): number {
  const xNum = /^\d+$/.test(x);
  const yNum = /^\d+$/.test(y);
  if (xNum && yNum) return cmpNum(x, y);
  if (xNum) return -1; // numeric identifiers sort before alphanumeric ones
  if (yNum) return 1;
  return x < y ? -1 : x > y ? 1 : 0;
}

// Semver precedence (build metadata ignored).
function comparePrecedence(x: Parsed, y: Parsed): number {
  for (let i = 0; i < 3; i++) {
    const c = cmpNum(x.core[i], y.core[i]);
    if (c !== 0) return c;
  }
  if (x.pre === null && y.pre === null) return 0;
  if (x.pre === null) return 1; // release > prerelease
  if (y.pre === null) return -1;

  const n = Math.min(x.pre.length, y.pre.length);
  for (let i = 0; i < n; i++) {
    const c = cmpPreId(x.pre[i], y.pre[i]);
    if (c !== 0) return c;
  }
  return x.pre.length === y.pre.length
    ? 0
    : x.pre.length < y.pre.length
      ? -1
      : 1;
}

// Index of the highest differing core part (0=major, 1=minor, 2=patch), or -1 if cores are equal.
function highestDiff(lo: [string, string, string], hi: [string, string, string]): number {
  for (let i = 0; i < 3; i++) {
    if (cmpNum(lo[i], hi[i]) !== 0) return i;
  }
  return -1;
}

const PARTS = ["major", "minor", "patch"];

export function solve(a: string, b: string): string | null {
  const pa = parse(a);
  const pb = parse(b);

  const c = comparePrecedence(pa, pb);
  if (c === 0) return null;

  const [lo, hi] = c < 0 ? [pa, pb] : [pb, pa];
  const idx = highestDiff(lo.core, hi.core);
  const hiIsPre = hi.pre !== null;
  const loIsPre = lo.pre !== null;

  // Higher version is a prerelease: "pre" + highest differing part, or "prerelease" if cores match.
  if (hiIsPre) {
    return idx === -1 ? "prerelease" : "pre" + PARTS[idx];
  }

  // Higher version is a release and lower is a prerelease: special cases.
  if (loIsPre) {
    const [, loMinor, loPatch] = lo.core;
    const [, hiMinor, hiPatch] = hi.core;

    // Lower minor and patch are 0 and only the major changed (or cores equal): major.
    if (loMinor === "0" && loPatch === "0" && hiMinor === "0" && hiPatch === "0") {
      return "major";
    }

    // Cores equal, lower patch is 0 (minor nonzero): minor; otherwise patch.
    if (idx === -1) {
      return loPatch === "0" ? "minor" : "patch";
    }
  }

  // Default: highest differing core part.
  return PARTS[idx];
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$/;

// A prerelease id must be a single alphanumeric identifier that starts with a letter or hyphen.
const ID_RE = /^[A-Za-z-][0-9A-Za-z-]*$/;
const NUMERIC_RE = /^\d+$/;

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  const m = SEMVER_RE.exec(version);
  if (!m) return null;

  const zero = BigInt(0);
  const one = BigInt(1);

  let major = BigInt(m[1]);
  let minor = BigInt(m[2]);
  let patch = BigInt(m[3]);
  // Build metadata (after '+') is discarded, as semver's inc does.
  let pre: string[] = m[4] !== undefined ? m[4].split('.') : [];

  const tag = id === undefined || id === '' ? undefined : id;

  // All pre* kinds start with "pre"; reject an invalid id only when it would be used.
  if (kind.startsWith('pre') && tag !== undefined && !ID_RE.test(tag)) {
    return null;
  }

  const newPre = (): string[] => (tag !== undefined ? [tag, '0'] : ['0']);

  switch (kind) {
    case 'major':
      // From a prerelease whose minor and patch are zero, major just releases it.
      if (!(pre.length > 0 && minor === zero && patch === zero)) {
        major += one;
      }
      minor = zero;
      patch = zero;
      pre = [];
      break;

    case 'minor':
      // From a prerelease whose patch is zero, minor just releases it.
      if (!(pre.length > 0 && patch === zero)) {
        minor += one;
      }
      patch = zero;
      pre = [];
      break;

    case 'patch':
      // From a prerelease, patch just releases it.
      if (pre.length === 0) {
        patch += one;
      }
      pre = [];
      break;

    case 'premajor':
      major += one;
      minor = zero;
      patch = zero;
      pre = newPre();
      break;

    case 'preminor':
      minor += one;
      patch = zero;
      pre = newPre();
      break;

    case 'prepatch':
      patch += one;
      pre = newPre();
      break;

    case 'prerelease': {
      if (pre.length === 0) {
        // Release: bump patch and start a new prerelease.
        patch += one;
        pre = newPre();
        break;
      }

      // A prerelease "has the same id" if its leading identifier matches the
      // requested id. With no id, that means the prerelease has no alphabetic prefix.
      const sameId = tag === undefined ? NUMERIC_RE.test(pre[0]) : pre[0] === tag;

      let bumped = false;
      if (sameId) {
        for (let i = pre.length - 1; i >= 0; i--) {
          if (NUMERIC_RE.test(pre[i])) {
            pre[i] = (BigInt(pre[i]) + one).toString();
            bumped = true;
            break;
          }
        }
      }
      if (!bumped) {
        // Different id, or no numeric part to increment: switch to <id>.0 (or 0).
        pre = newPre();
      }
      break;
    }

    default:
      return null;
  }

  const core = `${major}.${minor}.${patch}`;
  return pre.length > 0 ? `${core}-${pre.join('.')}` : core;
}

export function solve(name: string, namespace: string): string {
  const uuidPattern = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
  if (typeof namespace !== "string" || !uuidPattern.test(namespace)) {
    throw new TypeError("namespace is not a valid UUID");
  }

  // Namespace UUID -> 16 bytes
  const nsHex = namespace.replace(/-/g, "");
  const nsBytes: number[] = [];
  for (let i = 0; i < 32; i += 2) {
    nsBytes.push(parseInt(nsHex.substr(i, 2), 16));
  }

  // name -> UTF-8 bytes (lone surrogates are replaced by U+FFFD)
  const nameBytes = utf8Encode(String(name));

  const digest = md5(nsBytes.concat(nameBytes));

  // Set version (3) and RFC 4122 variant
  digest[6] = (digest[6] & 0x0f) | 0x30;
  digest[8] = (digest[8] & 0x3f) | 0x80;

  let hex = "";
  for (let i = 0; i < 16; i++) {
    const b = digest[i];
    hex += (b < 16 ? "0" : "") + b.toString(16);
  }

  return (
    hex.slice(0, 8) + "-" +
    hex.slice(8, 12) + "-" +
    hex.slice(12, 16) + "-" +
    hex.slice(16, 20) + "-" +
    hex.slice(20, 32)
  );
}

function utf8Encode(s: string): number[] {
  const out: number[] = [];
  for (const ch of s) {
    let cp = ch.codePointAt(0) as number;
    if (cp >= 0xd800 && cp <= 0xdfff) {
      cp = 0xfffd; // lone surrogate
    }
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }
  return out;
}

function md5(msg: number[]): number[] {
  const S: number[] = [
    7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
    5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
    4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
    6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
  ];

  const K: number[] = [];
  for (let i = 0; i < 64; i++) {
    K[i] = Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296);
  }

  const len = msg.length;
  const blocks = ((len + 8) >>> 6) + 1;
  const total = blocks * 64;
  const buf: number[] = [];
  for (let i = 0; i < total; i++) buf.push(0);
  for (let i = 0; i < len; i++) buf[i] = msg[i];
  buf[len] = 0x80;

  const bitLo = (len * 8) >>> 0;
  const bitHi = Math.floor(len / 0x20000000) >>> 0;
  for (let k = 0; k < 4; k++) {
    buf[total - 8 + k] = (bitLo >>> (8 * k)) & 0xff;
    buf[total - 4 + k] = (bitHi >>> (8 * k)) & 0xff;
  }

  let a0 = 0x67452301;
  let b0 = 0xefcdab89 | 0;
  let c0 = 0x98badcfe | 0;
  let d0 = 0x10325476;

  const M: number[] = new Array<number>(16);

  for (let off = 0; off < total; off += 64) {
    for (let j = 0; j < 16; j++) {
      const p = off + j * 4;
      M[j] = (buf[p] | (buf[p + 1] << 8) | (buf[p + 2] << 16) | (buf[p + 3] << 24)) | 0;
    }

    let A = a0;
    let B = b0;
    let C = c0;
    let D = d0;

    for (let i = 0; i < 64; i++) {
      let F: number;
      let g: number;
      if (i < 16) {
        F = (B & C) | (~B & D);
        g = i;
      } else if (i < 32) {
        F = (D & B) | (~D & C);
        g = (5 * i + 1) % 16;
      } else if (i < 48) {
        F = B ^ C ^ D;
        g = (3 * i + 5) % 16;
      } else {
        F = C ^ (B | ~D);
        g = (7 * i) % 16;
      }
      F = (F + A + K[i] + M[g]) | 0;
      A = D;
      D = C;
      C = B;
      const s = S[i];
      B = (B + ((F << s) | (F >>> (32 - s)))) | 0;
    }

    a0 = (a0 + A) | 0;
    b0 = (b0 + B) | 0;
    c0 = (c0 + C) | 0;
    d0 = (d0 + D) | 0;
  }

  const out: number[] = [];
  const words = [a0, b0, c0, d0];
  for (let w = 0; w < 4; w++) {
    for (let k = 0; k < 4; k++) {
      out.push((words[w] >>> (8 * k)) & 0xff);
    }
  }
  return out;
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  const s = isbn.replace(/[ -]/g, "");

  const isValidTen = (): boolean => {
    if (!/^[0-9]{9}[0-9X]$/.test(s)) return false;
    let sum = 0;
    for (let i = 0; i < 10; i++) {
      const ch = s[i];
      const d = ch === "X" ? 10 : ch.charCodeAt(0) - 48;
      sum += (10 - i) * d;
    }
    return sum % 11 === 0;
  };

  const isValidThirteen = (): boolean => {
    if (!/^[0-9]{13}$/.test(s)) return false;
    let sum = 0;
    for (let i = 0; i < 13; i++) {
      const d = s.charCodeAt(i) - 48;
      sum += i % 2 === 0 ? d : 3 * d;
    }
    return sum % 10 === 0;
  };

  if (version === 10) return isValidTen();
  if (version === 13) return isValidThirteen();
  return isValidTen() || isValidThirteen();
}

type Rule = {
  matches: (digits: string) => boolean;
  lengths: readonly number[];
};

const range = (lo: number, hi: number): number[] => {
  const out: number[] = [];
  for (let i = lo; i <= hi; i++) out.push(i);
  return out;
};

// True if the first `width` digits, read as a number, fall within [lo, hi].
const prefixInRange = (digits: string, width: number, lo: number, hi: number): boolean => {
  if (digits.length < width) return false;
  const prefix = Number(digits.slice(0, width));
  return prefix >= lo && prefix <= hi;
};

const RULES: readonly Rule[] = [
  // Visa
  { matches: d => d.startsWith("4"), lengths: [13, 16, 19] },
  // Mastercard
  {
    matches: d =>
      prefixInRange(d, 2, 51, 55) || prefixInRange(d, 4, 2221, 2720),
    lengths: [16],
  },
  // American Express
  { matches: d => d.startsWith("34") || d.startsWith("37"), lengths: [15] },
  // Discover
  {
    matches: d =>
      d.startsWith("6011") ||
      prefixInRange(d, 6, 622126, 622925) ||
      prefixInRange(d, 3, 644, 649) ||
      d.startsWith("65"),
    lengths: [16, 19],
  },
  // Diners Club
  {
    matches: d =>
      prefixInRange(d, 3, 300, 305) || d.startsWith("36") || d.startsWith("38"),
    lengths: range(14, 19),
  },
  // JCB
  { matches: d => prefixInRange(d, 4, 3528, 3589), lengths: range(16, 19) },
  // UnionPay
  { matches: d => d.startsWith("62"), lengths: range(16, 19) },
];

const luhn = (digits: string): boolean => {
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let n = digits.charCodeAt(i) - 48;
    if (double) {
      n *= 2;
      if (n > 9) n -= 9;
    }
    sum += n;
    double = !double;
  }
  return sum % 10 === 0;
};

export function solve(card: string): boolean {
  const digits = card.replace(/[ -]/g, "");
  if (!/^\d+$/.test(digits)) return false;

  const issuerOk = RULES.some(
    rule => rule.lengths.includes(digits.length) && rule.matches(digits)
  );

  return issuerOk && luhn(digits);
}

export function solve(isin: string): boolean {
  if (typeof isin !== "string") return false;

  // 2 uppercase letters, 9 uppercase alphanumerics, 1 digit check digit
  if (!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin)) return false;

  // Convert letters to numbers (A=10 ... Z=35), keeping digits as-is
  let digits = "";
  for (let i = 0; i < isin.length; i++) {
    const code = isin.charCodeAt(i);
    if (code >= 65 && code <= 90) {
      digits += String(code - 55); // 'A' (65) -> 10, 'Z' (90) -> 35
    } else {
      digits += isin[i];
    }
  }

  // Luhn algorithm over the full digit string, including the check digit
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48;
    if (double) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    double = !double;
  }

  return sum % 10 === 0;
}

