function levenshtein(a: string, b: string): number {
  if (a === b) return 0;
  const m = a.length;
  const n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;

  let prev: number[] = new Array<number>(n + 1);
  for (let j = 0; j <= n; j++) {
    prev[j] = j;
  }

  for (let i = 1; i <= m; i++) {
    const curr: number[] = new Array<number>(n + 1);
    curr[0] = i;
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(
        prev[j] + 1,        // deletion
        curr[j - 1] + 1,    // insertion
        prev[j - 1] + cost  // substitution (or match)
      );
    }
    prev = curr;
  }

  return prev[n];
}

export function solve(word: string, dictionary: string[]): string {
  if (dictionary.length === 0) return "";

  let best = dictionary[0];
  let bestDist = levenshtein(word, best);

  for (let i = 1; i < dictionary.length; i++) {
    const candidate = dictionary[i];
    const d = levenshtein(word, candidate);
    if (d < bestDist) {
      bestDist = d;
      best = candidate;
    }
  }

  return best;
}

