  }

  if (Array.isArray(value)) {
    const copy: unknown[] = new Array(value.length);
    memo.set(value, copy);
    for (const key of Object.keys(value)) {
      copy[key as any] = cloneValue((value as any)[key], memo);
    }
    return copy;
  }

  // Plain objects and other ordinary objects: keep the prototype, copy own properties.
  const copy = Object.create(Object.getPrototypeOf(value)) as Record<PropertyKey, unknown>;
  memo.set(value, copy);

  for (const key of Reflect.ownKeys(value)) {
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (!descriptor || !descriptor.enumerable) {
      continue;
    }
    if ("value" in descriptor) {
      Object.defineProperty(copy, key, {
        ...descriptor,
        value: cloneValue(descriptor.value, memo),
      });
    } else {
      // Accessor properties are copied by descriptor.
      Object.defineProperty(copy, key, descriptor);
    }
  }

  return copy;
}

export function solve(name: string, namespace: string): string {
  const nsHex = namespace.replace(/-/g, "");
  if (!/^[0-9a-fA-F]{32}$/.test(nsHex)) {
    throw new Error("namespace must be a UUID string");
  }

  const nsBytes: number[] = [];
  for (let i = 0; i < 32; i += 2) {
    nsBytes.push(parseInt(nsHex.slice(i, i + 2), 16));
  }

  const data = nsBytes.concat(utf8Encode(name));
  const hash = sha1(data);

  // RFC 4122 version 5 and variant bits
  hash[6] = (hash[6] & 0x0f) | 0x50;
  hash[8] = (hash[8] & 0x3f) | 0x80;

  let hex = "";
  for (let i = 0; i < 16; i++) {
    hex += (hash[i] + 0x100).toString(16).slice(1);
  }

  return (
    hex.slice(0, 8) + "-" +
    hex.slice(8, 12) + "-" +
    hex.slice(12, 16) + "-" +
    hex.slice(16, 20) + "-" +
    hex.slice(20, 32)
  );
}

function utf8Encode(s: string): number[] {
  const out: number[] = [];
  for (let i = 0; i < s.length; i++) {
    let cp = s.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < s.length) {
      const lo = s.charCodeAt(i + 1);
      if (lo >= 0xdc00 && lo <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
        i++;
      }
    }
    if (cp >= 0xd800 && cp <= 0xdfff) {
      cp = 0xfffd; // lone surrogate -> replacement character
    }
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }
  return out;
}

function rotl(x: number, n: number): number {
  return ((x << n) | (x >>> (32 - n))) >>> 0;
}

function sha1(msg: number[]): number[] {
  const bitLen = msg.length * 8;
  const padded = msg.slice();
  padded.push(0x80);
  while (padded.length % 64 !== 56) {
    padded.push(0);
  }

  // 64-bit big-endian message length
  const hi = Math.floor(bitLen / 0x100000000) >>> 0;
  const lo = bitLen >>> 0;
  padded.push(
    (hi >>> 24) & 0xff, (hi >>> 16) & 0xff, (hi >>> 8) & 0xff, hi & 0xff,
    (lo >>> 24) & 0xff, (lo >>> 16) & 0xff, (lo >>> 8) & 0xff, lo & 0xff
  );

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  const w: number[] = new Array(80);

  for (let off = 0; off < padded.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const j = off + t * 4;
      w[t] = ((padded[j] << 24) | (padded[j + 1] << 16) |
              (padded[j + 2] << 8) | padded[j + 3]) >>> 0;
    }
    for (let t = 16; t < 80; t++) {
      w[t] = rotl(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);
    }

    let a = h0, b = h1, c = h2, d = h3, e = h4;

    for (let t = 0; t < 80; t++) {
      let f: number;
      let k: number;
      if (t < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (t < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (t < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const temp = (rotl(a, 5) + (f >>> 0) + e + k + w[t]) >>> 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
  }

  const out: number[] = [];
  for (const h of [h0, h1, h2, h3, h4]) {
    out.push((h >>> 24) & 0xff, (h >>> 16) & 0xff, (h >>> 8) & 0xff, h & 0xff);
  }
  return out;
}

const BASE64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function base64Value(ch: string): number {
  const index = BASE64_ALPHABET.indexOf(ch);
  if (index < 0) {
    throw new Error(`Invalid base64 character: ${JSON.stringify(ch)}`);
  }
  return index;
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error("Invalid base64 length: must be a multiple of 4");
  }

  const bytes: number[] = [];

  for (let i = 0; i < text.length; i += 4) {
    const c0 = text[i];
    const c1 = text[i + 1];
    const c2 = text[i + 2];
    const c3 = text[i + 3];

    const isLastGroup = i + 4 === text.length;
    const pad2 = c2 === "=";
    const pad3 = c3 === "=";

    if ((pad2 || pad3) && !isLastGroup) {
      throw new Error("Invalid base64: padding only allowed at the end");
    }
    if (pad2 && !pad3) {
      throw new Error("Invalid base64: malformed padding");
    }

    const v0 = base64Value(c0);
    const v1 = base64Value(c1);
    const v2 = pad2 ? 0 : base64Value(c2);
    const v3 = pad3 ? 0 : base64Value(c3);

    bytes.push(((v0 << 2) | (v1 >> 4)) & 0xff);

    if (!pad2) {
      bytes.push((((v1 & 0x0f) << 4) | (v2 >> 2)) & 0xff);
    }
    if (!pad3) {
      bytes.push((((v2 & 0x03) << 6) | v3) & 0xff);
    }
  }

  return bytes;
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  const index = new Map<string, number>();
  nodes.forEach((name, i) => {
    if (index.has(name)) {
      throw new Error(`Duplicate node: ${name}`);
    }
    index.set(name, i);
  });

  const n = nodes.length;
  const adj: number[][] = Array.from({ length: n }, () => []);
  const indegree: number[] = new Array<number>(n).fill(0);

  for (const [a, b] of edges) {
    const ia = index.get(a);
    const ib = index.get(b);
    if (ia === undefined) {
      throw new Error(`Edge references unknown node: ${a}`);
    }
    if (ib === undefined) {
      throw new Error(`Edge references unknown node: ${b}`);
    }
    adj[ia].push(ib);
    indegree[ib]++;
  }

  // Min-heap of ready node indices, so ties are broken by input order.
  const heap: number[] = [];

  const push = (value: number): void => {
    heap.push(value);
    let i = heap.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent] <= heap[i]) break;
      [heap[parent], heap[i]] = [heap[i], heap[parent]];
      i = parent;
    }
  };

  const pop = (): number => {
    const top = heap[0];
    const last = heap.pop() as number;
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const left = 2 * i + 1;
        const right = left + 1;
        let smallest = i;
        if (left < heap.length && heap[left] < heap[smallest]) smallest = left;
        if (right < heap.length && heap[right] < heap[smallest]) smallest = right;
        if (smallest === i) break;
        [heap[smallest], heap[i]] = [heap[i], heap[smallest]];
        i = smallest;
      }
    }
    return top;
  };

  for (let i = 0; i < n; i++) {
    if (indegree[i] === 0) push(i);
  }

  const result: string[] = [];
  while (heap.length > 0) {
    const v = pop();
    result.push(nodes[v]);
    for (const w of adj[v]) {
      indegree[w]--;
      if (indegree[w] === 0) push(w);
    }
  }

  if (result.length !== n) {
    throw new Error("Edges contain a cycle");
  }

  return result;
}

export function solve(epochMs: number): string {
  if (!Number.isFinite(epochMs)) {
    throw new RangeError("Invalid time value");
  }

  // Floor so that instants before the epoch with fractional milliseconds
  // still map to the correct whole second.
  const d = new Date(Math.floor(epochMs));
  if (Number.isNaN(d.getTime())) {
    throw new RangeError("Invalid time value");
  }

  const pad = (n: number, width: number): string => String(n).padStart(width, "0");

  const year = d.getUTCFullYear();
  // Years 0000-9999 use four digits; others use ISO expanded form with sign and six digits.
  const yearStr =
    year >= 0 && year <= 9999
      ? pad(year, 4)
      : (year < 0 ? "-" : "+") + pad(Math.abs(year), 6);

  const month = pad(d.getUTCMonth() + 1, 2);
  const day = pad(d.getUTCDate(), 2);
  const hours = pad(d.getUTCHours(), 2);
  const minutes = pad(d.getUTCMinutes(), 2);
  const seconds = pad(d.getUTCSeconds(), 2);

  return `${yearStr}-${month}-${day}T${hours}:${minutes}:${seconds}Z`;
}

export function solve(text: string): string {
  // Step 1: UTF-8 encode the input manually (lone surrogates become U+FFFD, as TextEncoder does).
  const bytes: number[] = [];
  for (let i = 0; i < text.length; i++) {
    let cp = text.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < text.length) {
      const lo = text.charCodeAt(i + 1);
      if (lo >= 0xdc00 && lo <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
        i++;
      }
    }
    if (cp >= 0xd800 && cp <= 0xdfff) cp = 0xfffd;

    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  // Step 2: MD5 padding (RFC 1321 section 3.1 and 3.2).
  const K: number[] = [
    0xd76aa478, 0xe8c7b756, 0x242070db, 0xc1bdceee,
    0xf57c0faf, 0x4787c62a, 0xa8304613, 0xfd469501,
    0x698098d8, 0x8b44f7af, 0xffff5bb1, 0x895cd7be,
    0x6b901122, 0xfd987193, 0xa679438e, 0x49b40821,
    0xf61e2562, 0xc040b340, 0x265e5a51, 0xe9b6c7aa,
    0xd62f105d, 0x02441453, 0xd8a1e681, 0xe7d3fbc8,
    0x21e1cde6, 0xc33707d6, 0xf4d50d87, 0x455a14ed,
    0xa9e3e905, 0xfcefa3f8, 0x676f02d9, 0x8d2a4c8a,
    0xfffa3942, 0x8771f681, 0x6d9d6122, 0xfde5380c,
    0xa4beea44, 0x4bdecfa9, 0xf6bb4b60, 0xbebfbc70,
    0x289b7ec6, 0xeaa127fa, 0xd4ef3085, 0x04881d05,
    0xd9d4d039, 0xe6db99e5, 0x1fa27cf8, 0xc4ac5665,
    0xf4292244, 0x432aff97, 0xab9423a7, 0xfc93a039,
    0x655b59c3, 0x8f0ccc92, 0xffeff47d, 0x85845dd1,
    0x6fa87e4f, 0xfe2ce6e0, 0xa3014314, 0x4e0811a1,
    0xf7537e82, 0xbd3af235, 0x2ad7d2bb, 0xeb86d391,
  ];

  const S: number[] = [
    7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
    5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
    4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
    6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
  ];

  const origLen = bytes.length;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);

  // Message length in bits as 64-bit little-endian.
  const bitLo = (origLen * 8) >>> 0;
  const bitHi = Math.floor(origLen / 0x20000000) >>> 0;
  for (let k = 0; k < 4; k++) bytes.push((bitLo >>> (8 * k)) & 0xff);
  for (let k = 0; k < 4; k++) bytes.push((bitHi >>> (8 * k)) & 0xff);

  // Step 3: Initialize state.
  let a0 = 0x67452301 | 0;
  let b0 = 0xefcdab89 | 0;
  let c0 = 0x98badcfe | 0;
  let d0 = 0x10325476 | 0;

  // Step 4: Process each 512-bit block.
  for (let off = 0; off < bytes.length; off += 64) {
    const M: number[] = new Array<number>(16);
    for (let j = 0; j < 16; j++) {
      const p = off + 4 * j;
      M[j] = bytes[p] | (bytes[p + 1] << 8) | (bytes[p + 2] << 16) | (bytes[p + 3] << 24);
    }

    let A = a0;
    let B = b0;
    let C = c0;
    let D = d0;

    for (let i = 0; i < 64; i++) {
      let F: number;
      let g: number;
      if (i < 16) {
        F = (B & C) | (~B & D);
        g = i;
      } else if (i < 32) {
        F = (D & B) | (~D & C);
        g = (5 * i + 1) & 15;
      } else if (i < 48) {
        F = B ^ C ^ D;
        g = (3 * i + 5) & 15;
      } else {
        F = C ^ (B | ~D);
        g = (7 * i) & 15;
      }

      F = (F + A + K[i] + M[g]) | 0;
      A = D;
      D = C;
      C = B;
      const s = S[i];
      B = (B + ((F << s) | (F >>> (32 - s)))) | 0;
    }

    a0 = (a0 + A) | 0;
    b0 = (b0 + B) | 0;
    c0 = (c0 + C) | 0;
    d0 = (d0 + D) | 0;
  }

  // Step 5: Output digest as little-endian bytes in lowercase hex.
  let hex = "";
  for (const word of [a0, b0, c0, d0]) {
    for (let k = 0; k < 4; k++) {
      const b = (word >>> (8 * k)) & 0xff;
      hex += b.toString(16).padStart(2, "0");
    }
  }
  return hex;
}

const DATE_TIME =
  /^(\d{4})(?:-(\d{2})-(\d{2})|-W(\d{2})-(\d)|-(\d{3}))(?:T(\d{2}):(\d{2})(?::(\d{2})(?:[.,](\d+))?)?(Z|[+-]\d{2}:\d{2})?)?$/;

function isLeap(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, m: number): number {
  const table = [31, isLeap(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return table[m - 1];
}

function mod(n: number, k: number): number {
  return ((n % k) + k) % k;
}

// Days since 1970-01-01 for a proleptic Gregorian date (m: 1-12, d: 1-31).
function daysFromCivil(y: number, m: number, d: number): number {
  const yy = m <= 2 ? y - 1 : y;
  const era = Math.floor(yy / 400);
  const yoe = yy - era * 400;
  const mp = (m + 9) % 12; // March = 0
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

// ISO weekday: Monday = 1 ... Sunday = 7. 1970-01-01 was a Thursday.
function isoWeekday(days: number): number {
  return mod(days + 3, 7) + 1;
}

function weeksInYear(y: number): number {
  const p = (year: number): number =>
    mod(year + Math.floor(year / 4) - Math.floor(year / 100) + Math.floor(year / 400), 7);
  return p(y) === 4 || p(y - 1) === 3 ? 53 : 52;
}

function parseIso(input: unknown): number {
  if (typeof input !== "string") {
    throw new RangeError(`Not a valid date: ${String(input)}`);
  }
  const m = DATE_TIME.exec(input);
  if (m === null) {
    throw new RangeError(`Not a valid date: ${input}`);
  }

  const year = Number(m[1]);
  let days: number;

  if (m[2] !== undefined) {
    // Calendar date: YYYY-MM-DD
    const month = Number(m[2]);
    const day = Number(m[3]);
    if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) {
      throw new RangeError(`Not a valid date: ${input}`);
    }
    days = daysFromCivil(year, month, day);
  } else if (m[4] !== undefined) {
    // Week date: YYYY-Www-D
    const week = Number(m[4]);
    const weekday = Number(m[5]);
    if (weekday < 1 || weekday > 7 || week < 1 || week > weeksInYear(year)) {
      throw new RangeError(`Not a valid date: ${input}`);
    }
    const jan4 = daysFromCivil(year, 1, 4);
    const mondayOfWeek1 = jan4 - (isoWeekday(jan4) - 1);
    days = mondayOfWeek1 + (week - 1) * 7 + (weekday - 1);
  } else {
    // Ordinal date: YYYY-DDD
    const ordinal = Number(m[6]);
    const maxOrdinal = isLeap(year) ? 366 : 365;
    if (ordinal < 1 || ordinal > maxOrdinal) {
      throw new RangeError(`Not a valid date: ${input}`);
    }
    days = daysFromCivil(year, 1, 1) + ordinal - 1;
  }

  let timeMs = 0;
  let extraDays = 0;

  if (m[7] !== undefined) {
    const hour = Number(m[7]);
    const minute = Number(m[8]);
    const second = m[9] !== undefined ? Number(m[9]) : 0;
    const fraction = m[10] !== undefined ? m[10] : "";
    const millis = Number((fraction + "000").slice(0, 3));

    if (minute > 59 || second > 59) {
      throw new RangeError(`Not a valid date: ${input}`);
    }

    let effectiveHour = hour;
    if (hour === 24) {
      // ISO 8601 allows 24:00:00 to denote the end of a day.
      if (minute !== 0 || second !== 0 || /[1-9]/.test(fraction)) {
        throw new RangeError(`Not a valid date: ${input}`);
      }
      effectiveHour = 0;
      extraDays = 1;
    } else if (hour > 23) {
      throw new RangeError(`Not a valid date: ${input}`);
    }

    timeMs = ((effectiveHour * 60 + minute) * 60 + second) * 1000 + millis;
  }

  let offsetMinutes = 0;
  const tz = m[11];
  if (tz !== undefined && tz !== "Z") {
    const sign = tz[0] === "-" ? -1 : 1;
    const oh = Number(tz.slice(1, 3));
    const om = Number(tz.slice(4, 6));
    if (oh > 23 || om > 59) {
      throw new RangeError(`Not a valid date: ${input}`);
    }
    offsetMinutes = sign * (oh * 60 + om);
  }

  return (days + extraDays) * 86400000 + timeMs - offsetMinutes * 60000;
}

export function solve(stamps: string[]): number[] {
  return stamps.map((s) => parseIso(s)).sort((a, b) => a - b);
}

export function solve(versions: string[]): string[] {
  type Parsed = {
    full: string;
    core: string[];
    pre: string[] | null;
  };

  const parse = (v: string): Parsed => {
    const plus = v.indexOf("+");
    const noBuild = plus === -1 ? v : v.slice(0, plus);
    const dash = noBuild.indexOf("-");
    const coreStr = dash === -1 ? noBuild : noBuild.slice(0, dash);
    const pre = dash === -1 ? null : noBuild.slice(dash + 1).split(".");
    return { full: v, core: coreStr.split("."), pre };
  };

  // Compare non-negative integer strings (valid semver has no leading zeros)
  const cmpNum = (a: string, b: string): number => {
    if (a.length !== b.length) return a.length - b.length;
    return a < b ? -1 : a > b ? 1 : 0;
  };

  const isNumeric = (s: string): boolean => /^\d+$/.test(s);

  const cmpIdent = (a: string, b: string): number => {
    const aNum = isNumeric(a);
    const bNum = isNumeric(b);
    if (aNum && bNum) return cmpNum(a, b);
    if (aNum) return -1; // numeric identifiers have lower precedence
    if (bNum) return 1;
    return a < b ? -1 : a > b ? 1 : 0; // ASCII lexical order
  };

  const cmpPre = (a: string[], b: string[]): number => {
    const n = Math.min(a.length, b.length);
    for (let i = 0; i < n; i++) {
      const c = cmpIdent(a[i], b[i]);
      if (c !== 0) return c;
    }
    return a.length - b.length < 0 ? -1 : a.length === b.length ? 0 : 1;
  };

  const cmpParsed = (x: Parsed, y: Parsed): number => {
    for (let i = 0; i < 3; i++) {
      const c = cmpNum(x.core[i] ?? "0", y.core[i] ?? "0");
      if (c !== 0) return c;
    }

    let c: number;
    if (x.pre === null && y.pre === null) c = 0;
    else if (x.pre === null) c = 1; // release > prerelease
    else if (y.pre === null) c = -1;
    else c = cmpPre(x.pre, y.pre);

    if (c !== 0) return c;

    // Equal precedence: order by full string lexically
    return x.full < y.full ? -1 : x.full > y.full ? 1 : 0;
  };

  return versions
    .map(parse)
    .sort(cmpParsed)
    .map((p) => p.full);
}

export function solve(text: string): string {
  // UTF-8 encode the input manually (no TextEncoder, no Node/browser APIs).
  // Lone surrogates are replaced with U+FFFD, matching standard UTF-8 encoders.
  const bytes: number[] = [];
  for (const ch of text) {
    let cp = ch.codePointAt(0) as number;
    if (cp >= 0xd800 && cp <= 0xdfff) cp = 0xfffd;
    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  // Padding (FIPS 180-4 section 5.1.1)
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);

  const hi = Math.floor(bitLen / 4294967296);
  const lo = bitLen % 4294967296;
  bytes.push(
    (hi >>> 24) & 0xff, (hi >>> 16) & 0xff, (hi >>> 8) & 0xff, hi & 0xff,
    (lo >>> 24) & 0xff, (lo >>> 16) & 0xff, (lo >>> 8) & 0xff, lo & 0xff
  );

  const rotl = (x: number, n: number): number =>
    ((x << n) | (x >>> (32 - n))) >>> 0;

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  const w: number[] = new Array<number>(80).fill(0);

  for (let off = 0; off < bytes.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const i = off + t * 4;
      w[t] = ((bytes[i] << 24) | (bytes[i + 1] << 16) | (bytes[i + 2] << 8) | bytes[i + 3]) >>> 0;
    }
    for (let t = 16; t < 80; t++) {
      w[t] = rotl(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let t = 0; t < 80; t++) {
      let f: number;
      let k: number;
      if (t < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (t < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (t < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const temp = (rotl(a, 5) + (f >>> 0) + e + k + w[t]) >>> 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
  }

  return [h0, h1, h2, h3, h4]
    .map((x) => x.toString(16).padStart(8, "0"))
    .join("");
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;
const NUMERIC_RE = /^(0|[1-9]\d*)$/;
const ID_RE = /^[0-9A-Za-z-]+$/;

// Increments a non-negative decimal integer given as a string (no precision loss).
function incNumeric(s: string): string {
  const d = s.split('');
  let i = d.length - 1;
  while (i >= 0) {
    if (d[i] === '9') {
      d[i] = '0';
      i--;
    } else {
      d[i] = String.fromCharCode(d[i].charCodeAt(0) + 1);
      return d.join('');
    }
  }
  return '1' + d.join('');
}

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  if (typeof version !== 'string') return null;
  const m = SEMVER_RE.exec(version);
  if (!m) return null;
  if (id !== undefined && !ID_RE.test(id)) return null;

  let major = m[1];
  let minor = m[2];
  let patch = m[3];
  const hasPre = m[4] !== undefined;
  let pre: string[] = hasPre ? m[4].split('.') : [];

  switch (kind) {
    case 'major':
      // Releasing a prerelease whose minor and patch are already zero keeps the major.
      if (!hasPre || minor !== '0' || patch !== '0') {
        major = incNumeric(major);
      }
      minor = '0';
      patch = '0';
      pre = [];
      break;

    case 'minor':
      if (!hasPre || patch !== '0') {
        minor = incNumeric(minor);
      }
      patch = '0';
      pre = [];
      break;

    case 'patch':
      if (!hasPre) {
        patch = incNumeric(patch);
      }
      pre = [];
      break;

    case 'premajor':
      major = incNumeric(major);
      minor = '0';
      patch = '0';
      pre = id !== undefined ? [id, '0'] : ['0'];
      break;

    case 'preminor':
      minor = incNumeric(minor);
      patch = '0';
      pre = id !== undefined ? [id, '0'] : ['0'];
      break;

    case 'prepatch':
      patch = incNumeric(patch);
      pre = id !== undefined ? [id, '0'] : ['0'];
      break;

    case 'prerelease':
      if (!hasPre) {
        patch = incNumeric(patch);
        pre = id !== undefined ? [id, '0'] : ['0'];
      } else if (id === undefined || pre[0] === id) {
        let idx = -1;
        for (let i = pre.length - 1; i >= 0; i--) {
          if (NUMERIC_RE.test(pre[i])) {
            idx = i;
            break;
          }
        }
        if (idx >= 0) {
          pre = pre.slice();
          pre[idx] = incNumeric(pre[idx]);
        } else {
          pre = [...pre, '0'];
        }
      } else {
        pre = [id, '0'];
      }
      break;

    default:
      return null;
  }

  const core = `${major}.${minor}.${patch}`;
  return pre.length > 0 ? `${core}-${pre.join('.')}` : core;
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*)?$/;

interface ParsedVersion {
  core: [string, string, string];
  pre: string[];
}

function parseVersion(v: string): ParsedVersion {
  const m = SEMVER_RE.exec(v);
  if (!m) {
    throw new Error(`Invalid semver version: ${v}`);
  }
  return {
    core: [m[1], m[2], m[3]],
    pre: m[4] !== undefined ? m[4].split(".") : [],
  };
}

// Compare numeric strings without overflow (valid semver has no leading zeros).
function cmpNumeric(x: string, y: string): number {
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  if (x === y) return 0;
  return x < y ? -1 : 1;
}

function cmpPreId(x: string, y: string): number {
  const xNum = /^\d+$/.test(x);
  const yNum = /^\d+$/.test(y);
  if (xNum && yNum) return cmpNumeric(x, y);
  if (xNum) return -1;
  if (yNum) return 1;
  if (x === y) return 0;
  return x < y ? -1 : 1;
}

function cmpPre(x: string[], y: string[]): number {
  // A release (no prerelease) has higher precedence than any prerelease.
  if (x.length === 0 && y.length === 0) return 0;
  if (x.length === 0) return 1;
  if (y.length === 0) return -1;
  const n = Math.min(x.length, y.length);
  for (let i = 0; i < n; i++) {
    const c = cmpPreId(x[i], y[i]);
    if (c !== 0) return c;
  }
  if (x.length === y.length) return 0;
  return x.length < y.length ? -1 : 1;
}

function cmpVersions(x: ParsedVersion, y: ParsedVersion): number {
  for (let i = 0; i < 3; i++) {
    const c = cmpNumeric(x.core[i], y.core[i]);
    if (c !== 0) return c;
  }
  return cmpPre(x.pre, y.pre);
}

// Highest core part that differs between two cores (lo <= hi assumed).
function highestDiff(
  lo: ParsedVersion,
  hi: ParsedVersion
): "major" | "minor" | "patch" | null {
  if (lo.core[0] !== hi.core[0]) return "major";
  if (lo.core[1] !== hi.core[1]) return "minor";
  if (lo.core[2] !== hi.core[2]) return "patch";
  return null;
}

export function solve(a: string, b: string): string | null {
  const pa = parseVersion(a);
  const pb = parseVersion(b);

  const order = cmpVersions(pa, pb);
  if (order === 0) return null;

  const lo = order < 0 ? pa : pb;
  const hi = order < 0 ? pb : pa;

  const loHasPre = lo.pre.length > 0;
  const hiHasPre = hi.pre.length > 0;

  if (loHasPre && !hiHasPre) {
    // Lower is a prerelease, higher is a release.
    const d = highestDiff(lo, hi);
    if (d !== null) return d;

    // Cores are equal.
    if (lo.core[1] === "0" && lo.core[2] === "0") return "major";
    return lo.core[2] !== "0" ? "patch" : "minor";
  }

  // Otherwise, classify by the highest differing core part,
  // prefixed with "pre" if the higher version is a prerelease.
  const d = highestDiff(lo, hi);
  const prefix = hiHasPre ? "pre" : "";
  if (d !== null) return prefix + d;

  // Cores are equal (only possible when both are prereleases here).
  return "prerelease";
}

type Ver = { major: number; minor: number; patch: number; pre: string[] };
type Comp = { op: string; v: Ver };
type Parsed = { nums: (number | null)[]; pre: string[] };

const ver = (major: number, minor: number, patch: number, pre: string[] = []): Ver =>
  ({ major, minor, patch, pre });

function cmpNum(a: number, b: number): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

function compare(a: Ver, b: Ver): number {
  const c = cmpNum(a.major, b.major) || cmpNum(a.minor, b.minor) || cmpNum(a.patch, b.patch);
  if (c !== 0) return c;
  if (a.pre.length === 0 && b.pre.length === 0) return 0;
  if (a.pre.length === 0) return 1;
  if (b.pre.length === 0) return -1;
  const n = Math.min(a.pre.length, b.pre.length);
  for (let i = 0; i < n; i++) {
    const x = a.pre[i];
    const y = b.pre[i];
    if (x === y) continue;
    const xn = /^\d+$/.test(x);
    const yn = /^\d+$/.test(y);
    if (xn && yn) return cmpNum(Number(x), Number(y));
    if (xn) return -1;
    if (yn) return 1;
    return x < y ? -1 : 1;
  }
  return cmpNum(a.pre.length, b.pre.length);
}

function cmpOk(c: number, op: string): boolean {
  switch (op) {
    case "<": return c < 0;
    case "<=": return c <= 0;
    case ">": return c > 0;
    case ">=": return c >= 0;
    default: return c === 0;
  }
}

// Parses a possibly-partial version ("1", "1.2", "1.x.*", "v1.2.3-beta+build").
// Wildcards are represented as null. Returns null if malformed.
function parsePartial(s: string): Parsed | null {
  let body = s;
  if (body.startsWith("v")) body = body.slice(1);

  const plus = body.indexOf("+");
  if (plus >= 0) {
    const build = body.slice(plus + 1);
    if (!/^[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*$/.test(build)) return null;
    body = body.slice(0, plus);
  }

  let core = body;
  let preStr: string | null = null;
  const dash = body.indexOf("-");
  if (dash >= 0) {
    core = body.slice(0, dash);
    preStr = body.slice(dash + 1);
  }

  const parts = core.split(".");
  if (parts.length > 3) return null;

  const nums: (number | null)[] = [];
  let wild = false;
  for (let i = 0; i < 3; i++) {
    const p = parts[i];
    if (p === undefined || /^[xX*]$/.test(p)) {
      nums.push(null);
      wild = true;
      continue;
    }
    if (wild || !/^(0|[1-9]\d*)$/.test(p)) return null;
    nums.push(Number(p));
  }

  let pre: string[] = [];
  if (preStr !== null) {
    if (nums.includes(null)) return null;
    pre = preStr.split(".");
    for (const id of pre) {
      if (!/^[0-9A-Za-z-]+$/.test(id)) return null;
      if (/^\d+$/.test(id) && id.length > 1 && id[0] === "0") return null;
    }
  }
  return { nums, pre };
}

function parseVersion(s: string): Ver | null {
  const p = parsePartial(s.trim());
  if (!p || p.nums.includes(null)) return null;
  return ver(p.nums[0] as number, p.nums[1] as number, p.nums[2] as number, p.pre);
}

// Converts one comparator token into a list of AND-ed bounds.
// An empty list means "any version".
function parseComp(tok: string): Comp[] | null {
  const m = /^(<=|>=|<|>|=|~>|~|\^)?(.*)$/.exec(tok);
  if (!m) return null;
  const op = m[1] ?? "";
  const p = parsePartial(m[2]);
  if (!p) return null;
  const [M, mi, P] = p.nums;

  if (M === null) {
    if (op === "<" || op === ">") return [{ op: "<", v: ver(0, 0, 0, ["0"]) }]; // unsatisfiable
    return [];
  }

  if (mi === null) {
    switch (op) {
      case "": case "=": case "~": case "~>": case "^":
        return [{ op: ">=", v: ver(M, 0, 0) }, { op: "<", v: ver(M + 1, 0, 0, ["0"]) }];
      case ">": return [{ op: ">=", v: ver(M + 1, 0, 0) }];
      case ">=": return [{ op: ">=", v: ver(M, 0, 0) }];
      case "<": return [{ op: "<", v: ver(M, 0, 0, ["0"]) }];
      case "<=": return [{ op: "<", v: ver(M + 1, 0, 0, ["0"]) }];
    }
    return null;
  }

  if (P === null) {
    switch (op) {
      case "": case "=": case "~": case "~>":
        return [{ op: ">=", v: ver(M, mi, 0) }, { op: "<", v: ver(M, mi + 1, 0, ["0"]) }];
      case "^":
        return M > 0
          ? [{ op: ">=", v: ver(M, mi, 0) }, { op: "<", v: ver(M + 1, 0, 0, ["0"]) }]
          : [{ op: ">=", v: ver(0, mi, 0) }, { op: "<", v: ver(0, mi + 1, 0, ["0"]) }];
      case ">": return [{ op: ">=", v: ver(M, mi + 1, 0) }];
      case ">=": return [{ op: ">=", v: ver(M, mi, 0) }];
      case "<": return [{ op: "<", v: ver(M, mi, 0, ["0"]) }];
      case "<=": return [{ op: "<", v: ver(M, mi + 1, 0, ["0"]) }];
    }
    return null;
  }

  const v = ver(M, mi, P, p.pre);
  switch (op) {
    case "": case "=":
      return [{ op: "=", v }];
    case ">": case ">=": case "<": case "<=":
      return [{ op, v }];
    case "~": case "~>":
      return [{ op: ">=", v }, { op: "<", v: ver(M, mi + 1, 0, ["0"]) }];
    case "^": {
      const upper = M > 0
        ? ver(M + 1, 0, 0, ["0"])
        : mi > 0
          ? ver(0, mi + 1, 0, ["0"])
          : ver(0, 0, P + 1, ["0"]);
      return [{ op: ">=", v }, { op: "<", v: upper }];
    }
  }
  return null;
}

// Parses one alternative (no "||") into a comparator set.
function parseAlt(alt: string): Comp[] | null {
  const hy = /^(\S+)\s+-\s+(\S+)$/.exec(alt);
  if (hy) {
    const lo = parseComp(">=" + hy[1]);
    const hi = parseComp("<=" + hy[2]);
    if (!lo || !hi) return null;
    return [...lo, ...hi];
  }

  const toks = alt.replace(/(<=|>=|<|>|=|~>|~|\^)\s+/g, "$1").split(/\s+/);
  const comps: Comp[] = [];
  for (const t of toks) {
    const c = parseComp(t);
    if (!c) return null;
    comps.push(...c);
  }
  return comps;
}

function parseRange(range: string): Comp[][] | null {
  const out: Comp[][] = [];
  for (const raw of range.split("||")) {
    const alt = raw.trim();
    if (alt === "") {
      out.push([]);
      continue;
    }
    const comps = parseAlt(alt);
    if (!comps) return null;
    out.push(comps);
  }
  return out;
}

// Checks a comparator set, including the prerelease rule.
function testSet(comps: Comp[], v: Ver): boolean {
  for (const c of comps) {
    if (!cmpOk(compare(v, c.v), c.op)) return false;
  }
  if (v.pre.length > 0) {
    const ok = comps.some(
      (c) =>
        c.v.pre.length > 0 &&
        c.v.major === v.major &&
        c.v.minor === v.minor &&
        c.v.patch === v.patch
    );
    if (!ok) return false;
  }
  return true;
}

export function solve(installed: string[], range: string): string | null {
  const alts = parseRange(range);
  if (!alts) return null;

  let best: Ver | null = null;
  let bestStr: string | null = null;

  for (const s of installed) {
    const v = parseVersion(s);
    if (!v) continue;
    if (!alts.some((comps) => testSet(comps, v))) continue;
    if (best === null || compare(v, best) > 0) {
      best = v;
      bestStr = s;
    }
  }
  return bestStr;
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  const s = isbn.replace(/[ -]/g, "");

  const isValidIsbn10 = (): boolean => {
    if (!/^[0-9]{9}[0-9X]$/.test(s)) return false;
    let sum = 0;
    for (let i = 0; i < 10; i++) {
      const ch = s[i];
      const d = ch === "X" ? 10 : ch.charCodeAt(0) - 48;
      sum += (10 - i) * d;
    }
    return sum % 11 === 0;
  };

  const isValidIsbn13 = (): boolean => {
    if (!/^[0-9]{13}$/.test(s)) return false;
    let sum = 0;
    for (let i = 0; i < 13; i++) {
      const d = s.charCodeAt(i) - 48;
      sum += i % 2 === 0 ? d : 3 * d;
    }
    return sum % 10 === 0;
  };

  if (version === undefined) {
    return isValidIsbn10() || isValidIsbn13();
  }
  if (version === 10) {
    return isValidIsbn10();
  }
  if (version === 13) {
    return isValidIsbn13();
  }
  return false;
}

export function solve(name: string, namespace: string): string {
  const UUID_RE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
  if (typeof namespace !== "string" || !UUID_RE.test(namespace)) {
    throw new TypeError("namespace is not a valid UUID");
  }
  if (typeof name !== "string") {
    throw new TypeError("name must be a string");
  }

  // UTF-8 encode (lone surrogates become U+FFFD, matching TextEncoder behavior)
  const utf8Bytes = (s: string): number[] => {
    const out: number[] = [];
    for (const ch of s) {
      let cp = ch.codePointAt(0) as number;
      if (cp >= 0xd800 && cp <= 0xdfff) cp = 0xfffd;
      if (cp < 0x80) {
        out.push(cp);
      } else if (cp < 0x800) {
        out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
      } else if (cp < 0x10000) {
        out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
      } else {
        out.push(
          0xf0 | (cp >> 18),
          0x80 | ((cp >> 12) & 0x3f),
          0x80 | ((cp >> 6) & 0x3f),
          0x80 | (cp & 0x3f)
        );
      }
    }
    return out;
  };

  // MD5 over a byte array, returns 16 bytes
  const md5 = (data: number[]): number[] => {
    const K: number[] = [];
    for (let i = 0; i < 64; i++) {
      K[i] = Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296) | 0;
    }
    const S = [
      7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
      5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
      4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
      6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
    ];

    const msg = data.slice();
    const bitLenLo = (data.length * 8) >>> 0;
    const bitLenHi = Math.floor(data.length / 536870912) >>> 0; // (len*8) / 2^32

    msg.push(0x80);
    while (msg.length % 64 !== 56) msg.push(0);
    for (let i = 0; i < 4; i++) msg.push((bitLenLo >>> (8 * i)) & 0xff);
    for (let i = 0; i < 4; i++) msg.push((bitLenHi >>> (8 * i)) & 0xff);

    let a0 = 0x67452301 | 0;
    let b0 = 0xefcdab89 | 0;
    let c0 = 0x98badcfe | 0;
    let d0 = 0x10325476 | 0;

    for (let off = 0; off < msg.length; off += 64) {
      const M: number[] = [];
      for (let j = 0; j < 16; j++) {
        const p = off + j * 4;
        M[j] = msg[p] | (msg[p + 1] << 8) | (msg[p + 2] << 16) | (msg[p + 3] << 24);
      }

      let A = a0, B = b0, C = c0, D = d0;

      for (let i = 0; i < 64; i++) {
        let F: number;
        let g: number;
        if (i < 16) {
          F = (B & C) | (~B & D);
          g = i;
        } else if (i < 32) {
          F = (D & B) | (~D & C);
          g = (5 * i + 1) % 16;
        } else if (i < 48) {
          F = B ^ C ^ D;
          g = (3 * i + 5) % 16;
        } else {
          F = C ^ (B | ~D);
          g = (7 * i) % 16;
        }
        F = (F + A + K[i] + M[g]) | 0;
        A = D;
        D = C;
        C = B;
        B = (B + ((F << S[i]) | (F >>> (32 - S[i])))) | 0;
      }

      a0 = (a0 + A) | 0;
      b0 = (b0 + B) | 0;
      c0 = (c0 + C) | 0;
      d0 = (d0 + D) | 0;
    }

    const out: number[] = [];
    for (const w of [a0, b0, c0, d0]) {
      for (let i = 0; i < 4; i++) out.push((w >>> (8 * i)) & 0xff);
    }
    return out;
  };

  // Parse namespace UUID into bytes
  const nsHex = namespace.replace(/-/g, "");
  const nsBytes: number[] = [];
  for (let i = 0; i < 32; i += 2) {
    nsBytes.push(parseInt(nsHex.slice(i, i + 2), 16));
  }

  const hash = md5(nsBytes.concat(utf8Bytes(name)));

  // Set version (3) and variant (RFC 4122)
  hash[6] = (hash[6] & 0x0f) | 0x30;
  hash[8] = (hash[8] & 0x3f) | 0x80;

  const hex = hash.map((b) => ("0" + b.toString(16)).slice(-2)).join("");

  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20, 32)}`;
}

export function solve(isin: string): boolean {
  if (typeof isin !== "string") return false;

  // Two uppercase letters, nine uppercase alphanumerics, one digit check digit.
  if (!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin)) return false;

  // Convert letters to numbers (A=10 ... Z=35), keeping digits as-is.
  let digits = "";
  for (const ch of isin) {
    if (ch >= "A" && ch <= "Z") {
      digits += String(ch.charCodeAt(0) - 55);
    } else {
      digits += ch;
    }
  }

  // Luhn check over the full digit string, including the check digit.
  let sum = 0;
  let doubleIt = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48;
    if (doubleIt) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    doubleIt = !doubleIt;
  }

  return sum % 10 === 0;
}

type IssuerRule = {
  matches: (d: string) => boolean;
  lengths: readonly number[];
};

// True when the first `width` digits, read as a number, fall within [lo, hi].
function prefixInRange(d: string, width: number, lo: number, hi: number): boolean {
  if (d.length < width) return false;
  const p = Number(d.slice(0, width));
  return p >= lo && p <= hi;
}

const DINERS_LENGTHS: readonly number[] = [14, 15, 16, 17, 18, 19];
const JCB_LENGTHS: readonly number[] = [16, 17, 18, 19];
const UNIONPAY_LENGTHS: readonly number[] = [16, 17, 18, 19];

const ISSUERS: readonly IssuerRule[] = [
  // Visa
  {
    matches: (d) => d.startsWith("4"),
    lengths: [13, 16, 19],
  },
  // Mastercard
  {
    matches: (d) => prefixInRange(d, 2, 51, 55),
    lengths: [16],
  },
  {
    matches: (d) => prefixInRange(d, 4, 2221, 2720),
    lengths: [16],
  },
  // American Express
  {
    matches: (d) => d.startsWith("34") || d.startsWith("37"),
    lengths: [15],
  },
  // Discover
  {
    matches: (d) =>
      d.startsWith("6011") ||
      prefixInRange(d, 6, 622126, 622925) ||
      prefixInRange(d, 3, 644, 649) ||
      d.startsWith("65"),
    lengths: [16, 19],
  },
  // Diners Club
  {
    matches: (d) =>
      prefixInRange(d, 3, 300, 305) || d.startsWith("36") || d.startsWith("38"),
    lengths: DINERS_LENGTHS,
  },
  // JCB
  {
    matches: (d) => prefixInRange(d, 4, 3528, 3589),
    lengths: JCB_LENGTHS,
  },
  // UnionPay
  {
    matches: (d) => d.startsWith("62"),
    lengths: UNIONPAY_LENGTHS,
  },
];

function luhn(d: string): boolean {
  let sum = 0;
  let double = false;
  for (let i = d.length - 1; i >= 0; i--) {
    let n = d.charCodeAt(i) - 48;
    if (double) {
      n *= 2;
      if (n > 9) n -= 9;
    }
    sum += n;
    double = !double;
  }
  return sum % 10 === 0;
}

export function solve(card: string): boolean {
  const d = card.replace(/[\s-]/g, "");
  if (!/^\d+$/.test(d)) return false;

  const len = d.length;
  const issuerOk = ISSUERS.some(
    (issuer) => issuer.lengths.includes(len) && issuer.matches(d)
  );

  return issuerOk && luhn(d);
}

export function solve(mac: string): boolean {
  const patterns: RegExp[] = [
    // EUI-48 with colons: 6 octets
    /^[0-9a-f]{2}(?::[0-9a-f]{2}){5}$/i,
    // EUI-64 with colons: 8 octets
    /^[0-9a-f]{2}(?::[0-9a-f]{2}){7}$/i,
    // EUI-48 with hyphens: 6 octets
    /^[0-9a-f]{2}(?:-[0-9a-f]{2}){5}$/i,
    // EUI-64 with hyphens: 8 octets
    /^[0-9a-f]{2}(?:-[0-9a-f]{2}){7}$/i,
    // Dotted form, 3 groups of 4 hex digits
    /^[0-9a-f]{4}(?:\.[0-9a-f]{4}){2}$/i,
    // Dotted form, 4 groups of 4 hex digits
    /^[0-9a-f]{4}(?:\.[0-9a-f]{4}){3}$/i,
  ];
  return patterns.some((p) => p.test(mac));
}

type IbanFormat = { readonly length: number; readonly bban: string };

// BBAN specs: each token is <count><type>, where n = digits, a = uppercase letters, c = alphanumeric.
