export function solve(iban: string): boolean {
  if (typeof iban !== "string") return false;

  // Strip spaces and hyphens, then validate ASCII before normalising case
  // (guards against non-ASCII characters that uppercase into ASCII letters).
  const raw = iban.replace(/[\s-]/g, "");
  if (!/^[A-Za-z0-9]+$/.test(raw)) return false;

  const s = raw.toUpperCase();
  if (!/^[A-Z]{2}[0-9]{2}[A-Z0-9]+$/.test(s)) return false;

  const spec = SPECS.get(s.slice(0, 2));
  if (spec === undefined || s.length !== spec.length) return false;
  if (!spec.pattern.test(s.slice(4))) return false;

  // Mod-97 check: move the first four characters to the end,
  // map A=10 ... Z=35, and compute the remainder without BigInt.
  const rearranged = s.slice(4) + s.slice(0, 4);
  let remainder = 0;
  for (const ch of rearranged) {
    const code = ch.charCodeAt(0);
    if (code >= 48 && code <= 57) {
      // digit '0'..'9'
      remainder = (remainder * 10 + (code - 48)) % 97;
    } else {
      // letter 'A'..'Z' -> two-digit value 10..35
      remainder = (remainder * 100 + (code - 55)) % 97;
    }
  }

  return remainder === 1;
}

